/* Role-specific chapter guides aligned to the 16-track industry curriculum.
 * Original case figures and campaign outcomes are SIMULATED. No client results are implied.
 * Each chapter follows LEARN -> BUILD -> VERIFY and uses role-specific work products.
 */
function G(concept,example,steps,practice,checks,terms,chapterId){
 return {chapterId:chapterId||null,concept:concept,example:example,steps:steps,practice:practice,checks:checks.map(function(x){return {q:x[0],a:x[1]};}),terms:terms.map(function(x){return {term:x[0],definition:x[1]};})};
}
var ROLE_STUDY_GUIDES = {
connection:[
G("Connection Planning dimulai dengan memisahkan business problem, marketing problem, dan communication problem. Penjualan turun bisa terjadi karena harga, distribusi, stok, produk, atau pengalaman; tidak semuanya dapat diselesaikan oleh komunikasi. Planner harus menulis masalah yang dapat dipengaruhi komunikasi, mendefinisikan audience, perubahan perilaku/persepsi yang diharapkan, baseline, periode, dan constraint. Brief yang baik menghasilkan pertanyaan riset dan keputusan, bukan langsung daftar channel.",
"SIMULATED — sebuah brand minuman mengalami penurunan trial. Data menunjukkan awareness tinggi tetapi pemahaman benefit rendah pada segmen pekerja malam. Distribusi dan harga stabil. Communication challenge yang masuk akal adalah memperjelas relevansi benefit pada momen konsumsi, bukan sekadar menaikkan reach.",
["<b>Audit brief.</b> Pisahkan objective bisnis, gejala, evidence, audience, market, budget, timeline, mandatories, dan hal yang belum diketahui.","<b>Diagnosis controllability.</b> Tandai faktor yang dapat dipengaruhi komunikasi dan faktor produk/komersial yang perlu owner lain.","<b>Tulis problem statement.</b> Nyatakan siapa, perubahan apa, barrier apa, mengapa sekarang, dan evidence pendukungnya.","<b>Set success criteria.</b> Tentukan baseline, desired change, indikator komunikasi, business outcome pendamping, periode, dan source."],
"Buat brief diagnosis dua halaman: business context, problem tree, communication challenge, target audience, objective, baseline/target, constraint, stakeholder, tiga research question, serta evidence/assumption log. Labeli setiap angka SIMULATED bila bukan data aktual.",
[["Apa beda business problem dan communication problem?","Business problem adalah hasil komersial yang perlu berubah; communication problem adalah hambatan persepsi, pemahaman, preference, atau tindakan yang memang dapat dipengaruhi komunikasi."],["Mengapa brief tidak boleh langsung berisi channel?","Channel baru dipilih setelah audience, barrier, objective, dan journey dipahami. Memulai dari channel berisiko mengoptimalkan media untuk masalah yang salah."],["Bagaimana membuktikan sebuah masalah berada dalam kendali komunikasi?","Triangulasikan riset audience, perilaku, pesan yang diterima, dan faktor komersial seperti harga/stok. Catat faktor yang tidak dapat dikendalikan planner."]],
[["Communication challenge","Hambatan komunikasi yang menghalangi perubahan pemahaman, persepsi, atau perilaku."],["Baseline","Kondisi awal yang menjadi pembanding untuk menilai perubahan."],["Mandatories","Ketentuan wajib dari klien, brand, legal, budget, atau campaign."],["Problem statement","Pernyataan terfokus tentang masalah, audience, barrier, dan perubahan yang dibutuhkan."]],"DPA-T02-CH01"),
G("Audience research menggabungkan data primer seperti interview, survey, observation, dan usability research dengan data sekunder seperti sales, CRM, search, review, social listening, dan syndicated studies. Segmentasi harus menjelaskan kebutuhan, perilaku, motivasi, konteks, trigger, dan decision criteria yang memengaruhi strategi. Demografi dapat membantu sizing, tetapi tidak otomatis menjadi insight. Planner perlu menilai kualitas sample, recency, bias, representativeness, dan batas inferensi.",
"SIMULATED — dua kelompok usia 25–34 sama-sama membeli skincare. Satu kelompok mencari rutinitas ringkas untuk perjalanan; kelompok lain mencari kepastian bahan karena pengalaman iritasi. Keduanya memiliki tension dan proof requirement berbeda walau demografinya sama.",
["<b>Rumuskan research question.</b> Tulis keputusan yang perlu didukung dan ketidakpastian yang harus dikurangi sebelum memilih metode.","<b>Triangulasikan sumber.</b> Cocokkan search/review/CRM dengan interview atau survey; jangan menjadikan satu social post sebagai representasi seluruh pasar.","<b>Bangun segment.</b> Definisikan need, occasion, trigger, barrier, behavior, alternative, decision criteria, dan media context.","<b>Dokumentasikan evidence.</b> Pisahkan observed fact, interpretation, assumption, confidence, sample limitation, serta bukti yang dapat membantah."],
"Buat dua audience profile lengkap dengan jobs-to-be-done, tension, trigger, barrier, alternatives, proof needed, media behavior, dan implication untuk pesan/touchpoint. Sertakan source log dan satu research gap per segmen.",
[["Mengapa persona demografis saja tidak cukup?","Demografi membantu mendeskripsikan populasi, tetapi tidak menjelaskan motivasi, trigger, hambatan, atau bukti yang diperlukan untuk mengambil keputusan."],["Apa risiko memakai social listening sebagai satu-satunya riset?","Percakapan publik tidak selalu representatif, dapat bias platform, loud minority, dan tidak selalu menjelaskan sebab perilaku."],["Kapan segmentasi layak digunakan untuk strategi?","Saat segmen memiliki kebutuhan/perilaku berbeda yang mengubah proposition, channel, experience, atau keputusan investasi."]],
[["Primary research","Data yang dikumpulkan langsung untuk menjawab research question tertentu."],["Secondary research","Data yang telah dikumpulkan pihak lain atau tersedia dari sistem bisnis."],["Behavioral segment","Kelompok audience yang dibedakan melalui perilaku, kebutuhan, atau konteks."],["Evidence log","Catatan sumber, tanggal, metode, temuan, dan batas interpretasi."]],"DPA-T02-CH02"),
G("Cultural insight menghubungkan perubahan konteks budaya, perilaku nyata, kebutuhan manusia, dan ketegangan yang relevan dengan kategori. Tren hanya sinyal; insight menjelaskan mengapa sinyal tersebut penting bagi audience dan brand. Human tension biasanya memuat dua kebutuhan yang bertabrakan. Planner menguji skala, momentum, durasi, relevansi kategori, dan risiko appropriation sebelum mengusulkan platform ide.",
"SIMULATED — tren konten nostalgia meningkat, tetapi itu belum otomatis menjadi insight. Riset dapat menunjukkan pekerja muda mencari rasa aman di tengah perubahan kerja; nostalgia menjadi salah satu ekspresi, bukan keseluruhan kebutuhan. Brand harus punya peran yang kredibel untuk masuk.",
["<b>Kumpulkan cultural signals.</b> Baca percakapan, search, creator, komunitas, berita, riset, perilaku kategori, dan perubahan sosial.","<b>Bedakan signal, trend, shift.</b> Ukur apakah sinyal hanya viral sesaat atau mengindikasikan perubahan perilaku lebih luas.","<b>Formulasikan tension.</b> Tulis pola audience ingin X tetapi mengalami Y karena Z; dukung dengan beberapa bukti independen.","<b>Uji brand fit.</b> Tentukan peran brand, relevance, credibility, timing, sensitivity, dan potensi backlash."],
"Buat cultural insight board berisi lima sinyal, dua tren, satu human tension, evidence pro/kontra, brand role, serta tiga potential communication territories. Jangan mengklaim hubungan kausal dari korelasi tren.",
[["Apa beda trend dan insight?","Trend menunjukkan pola/sinyal yang berkembang; insight menjelaskan motivasi atau tension yang mendasari perilaku dan mengarahkan keputusan."],["Mengapa insight harus punya evidence yang dapat membantahnya?","Tanpa falsifiability, insight mudah menjadi slogan yang terdengar menarik tetapi tidak dapat diuji atau dipakai mengambil keputusan."],["Apa yang dimaksud brand fit dalam cultural moment?","Kesesuaian antara nilai, pengalaman, kompetensi, dan peran nyata brand dengan isu yang ingin dimasuki."]],
[["Cultural signal","Indikasi awal perubahan percakapan atau perilaku budaya."],["Human tension","Konflik dua kebutuhan atau keinginan yang dialami audience."],["Cultural relevance","Keterkaitan isu atau perilaku dengan audience dan konteks kategori."],["Brand fit","Kredibilitas dan kesesuaian peran brand dalam sebuah konteks."]],"DPA-T02-CH03"),
G("Positioning menentukan ruang pembeda brand relatif terhadap alternatif. Proposition menerjemahkan positioning menjadi nilai yang dijanjikan kepada audience; proof points membuat janji dapat dipercaya; objections menjelaskan alasan audience mungkin ragu. Communication strategy menentukan perubahan audience yang diharapkan, pesan yang perlu dibangun, dan cara mengatasi barrier. Jangan menyamakan tagline, key message, proposition, dan creative idea.",
"SIMULATED — dua layanan sama-sama menjanjikan pengiriman cepat. Brand A memiliki jaringan same-day di kota tertentu; Brand B hanya memberi estimasi umum. Proof point dan batas geografis menentukan klaim yang boleh digunakan.",
["<b>Petakan competitive frame.</b> Tentukan kategori, alternatif langsung/tidak langsung, parity points, dan pembeda yang relevan bagi audience.","<b>Rumuskan value proposition.</b> Hubungkan target, need, benefit, differentiation, reason-to-believe, dan limitation.","<b>Bangun messaging hierarchy.</b> Pisahkan proposition, supporting message, proof, objection response, tone, dan CTA.","<b>Uji konsistensi.</b> Periksa apakah pesan dapat dibuktikan, relevan pada journey, berbeda dari kompetitor, dan dapat diadaptasi lintas channel."],
"Susun positioning statement, value proposition, 3 proof points, 3 objections beserta respons, messaging hierarchy, dan satu communication strategy statement. Tandai klaim yang membutuhkan persetujuan legal atau validasi produk.",
[["Apa perbedaan proposition dan tagline?","Proposition menjelaskan nilai dan alasan memilih brand; tagline adalah ekspresi kreatif singkat yang dapat menjadi salah satu bentuk komunikasi."],["Mengapa proof point tidak boleh dibuat hanya dari copywriting?","Proof harus berasal dari fakta produk, data, sertifikasi, pengalaman, atau bukti yang dapat diverifikasi. Klaim tanpa dasar menimbulkan risiko reputasi/legal."],["Bagaimana menguji messaging hierarchy?","Pastikan pesan utama konsisten, supporting messages menjawab barrier, proof dapat diverifikasi, dan CTA sesuai tahap journey."]],
[["Positioning","Ruang pembeda yang ingin dimiliki brand relatif terhadap alternatif."],["Value proposition","Nilai/manfaat yang dijanjikan kepada target audience."],["Reason to believe","Bukti yang mendukung janji atau proposition."],["Message hierarchy","Urutan pesan utama, pendukung, proof, objection, dan CTA."]],"DPA-T02-CH04"),
G("Customer journey memetakan bagaimana audience bergerak dari kebutuhan hingga penggunaan, pembelian ulang, atau advocacy. Journey tidak selalu linear dan sering melibatkan offline, marketplace, search, creator, customer service, dan word-of-mouth. Moment of truth adalah titik pengalaman yang sangat memengaruhi keputusan. Touchpoint audit menilai audience need, brand role, friction, consistency, owner, dan evidence pada tiap momen.",
"SIMULATED — calon pembeli membandingkan produk di marketplace, melihat review creator, mengecek harga di toko, lalu bertanya tentang garansi melalui customer service. Mengoptimasi hanya iklan awareness akan melewatkan titik yang paling menentukan conversion: trust dan kepastian layanan.",
["<b>Tentukan journey boundary.</b> Pilih persona/occasion dan definisikan awal serta akhir journey yang dianalisis.","<b>Petakan tindakan dan pertanyaan.</b> Catat trigger, task, emotion, information need, influence, dan barrier pada setiap stage.","<b>Inventaris touchpoint.</b> Tandai paid/owned/earned/shared/offline, role, owner, content, data signal, dan handoff.","<b>Prioritaskan moments.</b> Nilai impact, friction, reach, feasibility, dan bukti; hindari memberi bobot sama pada semua touchpoint."],
"Buat journey map minimal enam tahap yang berisi audience action, question, emotion, friction, touchpoint, brand role, owner, evidence, dan opportunity. Pilih tiga moments of truth dan jelaskan alasan prioritas.",
[["Mengapa journey tidak selalu funnel linear?","Audience dapat bolak-balik, melompat, dipengaruhi marketplace/offline, dan menerima rekomendasi sebelum atau sesudah search."],["Apa beda touchpoint dengan channel?","Channel adalah medium/distribusi; touchpoint adalah interaksi spesifik yang dialami audience pada konteks dan waktu tertentu."],["Bagaimana memilih moment of truth?","Gunakan evidence dampak pada keputusan, intensitas friction, frekuensi/reach, dan kemampuan brand memperbaiki pengalaman."]],
[["Customer journey","Urutan tindakan dan pengalaman audience lintas waktu/touchpoint."],["Moment of truth","Interaksi penting yang dapat mengubah persepsi atau keputusan."],["Touchpoint","Kontak spesifik antara audience dan brand/ekosistem."],["Handoff","Perpindahan tanggung jawab atau pengalaman antar tim/channel."]],"DPA-T02-CH05"),
G("Paid, Owned, Earned, dan Shared menjelaskan karakter distribusi, bukan empat silo yang berdiri sendiri. Connection Planner memberi setiap channel tugas yang jelas: create demand, explain, validate, capture intent, convert, serve, retain, atau amplify advocacy. Pilihan dipengaruhi audience, trust, control, reach, context, timing, cost, frequency, dan measurement. Channel role harus berasal dari journey dan proposition, bukan tren platform.",
"SIMULATED — campaign launch menggunakan creator untuk credibility, social video untuk reach, search untuk menangkap demand aktif, landing page untuk menjelaskan proof, dan CRM untuk onboarding customer berizin. Setiap channel memiliki objective dan KPI berbeda.",
["<b>Turunkan tugas channel dari journey.</b> Tuliskan perubahan audience yang perlu terjadi pada tiap momen sebelum memilih media.","<b>Bandingkan channel fit.</b> Nilai audience availability, intent, trust, format, control, reach/frequency, cost, speed, dan risk.","<b>Susun role matrix.</b> Hubungkan channel dengan audience, message, task, KPI, CTA, owner, dan handoff.","<b>Uji overlap dan gap.</b> Temukan duplikasi pesan, momen tanpa dukungan, dan potensi konflik antar channel."],
"Buat channel-role matrix untuk minimal enam channel. Cantumkan task, audience, message, format, KPI, timing, dependency, owner, serta alasan channel dipilih atau ditolak.",
[["Mengapa channel tidak dipilih hanya berdasarkan CPM termurah?","Biaya exposure tidak menjelaskan trust, intent, attention, experience, conversion, atau contribution terhadap outcome."],["Apa fungsi shared media?","Distribusi atau penyebaran yang didorong partisipasi audience, creator, komunitas, atau jaringan sosial; bukan sepenuhnya dibeli atau dikontrol brand."],["Bagaimana menghindari channel silos?","Gunakan satu journey dan messaging architecture, tentukan handoff, shared measurement, owner, dan aturan frekuensi/sequence."]],
[["PESO","Paid, Earned, Shared, Owned sebagai kerangka distribusi."],["Channel role","Tugas spesifik channel dalam journey dan strategi komunikasi."],["Frequency","Rata-rata jumlah exposure pada audience dalam periode tertentu."],["Handoff","Transisi audience atau pekerjaan antar touchpoint/tim."]],"DPA-T02-CH06"),
G("Communication Architecture mengatur hubungan antara audience, pesan, channel, sequence, dan experience agar komunikasi terasa sebagai satu sistem. Messaging Framework menerjemahkan proposition menjadi message house, proof, objection, CTA, dan format. Konsistensi berarti janji brand tidak berubah; adaptasi berarti ekspresi dan proof disesuaikan dengan konteks platform serta kebutuhan audience.",
"SIMULATED — pesan launch yang sama tidak dapat dipakai verbatim pada search ad, video creator, product page, dan CRM. Proposition tetap konsisten, tetapi search menjawab intent, video membangun relevance, product page memberi detail/proof, CRM membantu onboarding.",
["<b>Buat architecture map.</b> Hubungkan audience segment, journey stage, objective, message, channel, format, dan timing.","<b>Susun message house.</b> Tetapkan single-minded proposition, supporting pillars, proof, objection handling, CTA, dan tone.","<b>Adaptasi per konteks.</b> Bedakan platform-native expression, panjang pesan, format, urgency, dan depth tanpa mengubah janji inti.","<b>Dokumentasikan governance.</b> Tetapkan owner, approval, versioning, claim validation, dan aturan update."],
"Bangun communication architecture satu campaign, message house, messaging matrix enam touchpoint, sequence/timing plan, dan governance/approval checklist. Sertakan contoh pesan per platform dan alasan adaptasinya.",
[["Apa risiko pesan terlalu seragam di semua channel?","Pesan dapat kehilangan relevansi konteks dan intent; audience dipaksa menerima format yang tidak sesuai tahap atau kebutuhan."],["Apa risiko pesan terlalu berbeda antar-channel?","Brand promise menjadi tidak konsisten, proof saling bertentangan, dan audience menerima pengalaman terputus."],["Apa yang dimaksud architecture, bukan sekadar content calendar?","Architecture menentukan hubungan strategis audience, objective, message, channel, sequence, dan experience; calendar hanya menempatkan aktivitas pada waktu."]],
[["Communication architecture","Sistem hubungan antara audience, message, channel, sequence, dan experience."],["Message house","Struktur proposition, supporting pillars, proof, objection, dan CTA."],["Single-minded proposition","Satu gagasan nilai utama yang ingin audience pahami/ingat."],["Version control","Aturan perubahan dan persetujuan aset/pesan agar konsisten."]],"DPA-T02-CH07"),
G("Creative brief menerjemahkan strategy menjadi arahan yang dapat dikerjakan creative, content, media, CXM, dan production team. Brief harus menjelaskan problem, audience, insight, proposition, desired response, mandatory, channel context, deliverables, timing, budget, measurement, dan constraint. Orchestration memastikan aset, pesan, dan experience tersambung; handoff bukan hanya mengirim deck, tetapi memastikan pemilik, spesifikasi, dependencies, dan approval jelas.",
"SIMULATED — tim creative menerima brief 'buat konten viral'. Brief itu gagal karena tidak menyebut audience tension, single-minded proposition, proof, objective, format, deliverable, dan success criteria. Rebrief mengubahnya menjadi challenge yang dapat dieksekusi dan dievaluasi.",
["<b>Tulis creative task.</b> Terangkan apa yang harus dipikirkan/dirasakan/dilakukan audience setelah menerima komunikasi.","<b>Definisikan deliverable.</b> Tetapkan channel, format, asset count, specification, message, CTA, mandatory, timing, dan budget.","<b>Rancang orchestration.</b> Susun sequence, dependency, version, owner, media placement, landing/experience, dan service readiness.","<b>Jalankan handoff.</b> Review brief bersama stakeholder, catat keputusan, approval, risk, dan change request."],
"Buat creative brief, channel adaptation matrix, asset/deliverable schedule, RACI/owner table, approval checklist, dan risk register untuk satu integrated campaign.",
[["Apa bedanya creative brief dan media brief?","Creative brief mengarahkan ide/pesan/pengalaman; media brief mengarahkan target, channel, inventory, budget, timing, dan delivery."],["Mengapa desired response harus jelas?","Agar creative team mengerti perubahan audience yang dituju dan dapat menilai apakah ide bekerja untuk objective."],["Apa bukti handoff berhasil?","Owner menerima brief dan aset dengan konteks, spesifikasi, deadline, KPI, approval, dependency, serta kriteria QA yang disepakati."]],
[["Creative brief","Dokumen arahan problem, audience, insight, message, response, dan execution constraints."],["RACI","Kerangka Responsible, Accountable, Consulted, Informed untuk penugasan."],["Orchestration","Pengaturan sequence, timing, dan keterkaitan interaksi lintas channel."],["Change request","Permintaan perubahan scope/brief yang harus dievaluasi dampaknya."]],"DPA-T02-CH08"),
G("Communication effectiveness menilai apakah komunikasi mencapai perubahan yang ditargetkan, bukan hanya apakah media deliver sesuai rencana. Pisahkan output (impressions, reach, views), outtake (attention, recall, comprehension, consideration), dan outcome (trial, sales, retention). Susun learning agenda sebelum campaign agar measurement dapat membantu keputusan berikutnya. Attribution platform tidak otomatis membuktikan causal impact.",
"SIMULATED — video campaign menghasilkan reach besar, tetapi brand recall tidak bergerak. Survey kecil menunjukkan audience mengingat kategori, bukan brand. Evaluasi menemukan brand cue muncul terlalu akhir; rekomendasi kreatif perlu diuji, bukan menyimpulkan reach gagal.",
["<b>Turunkan measurement objective.</b> Definisikan output, outtake, outcome, baseline, target, audience, dan time window.","<b>Pilih bukti sesuai pertanyaan.</b> Platform reporting untuk delivery; survey/brand lift untuk perception; sales/CRM untuk behavior; eksperimen untuk incrementality jika feasible.","<b>Susun learning agenda.</b> Tulis hipotesis, metode, sample, decision threshold, owner, dan kapan hasil mengubah rencana.","<b>Interpretasikan batas.</b> Pisahkan korelasi, attribution, self-reported lift, causal evidence, dan faktor luar."],
"Rancang measurement framework campaign dengan KPI output/outtake/outcome, measurement method, baseline, target, learning question, decision rule, dan limitation. Tulis satu rekomendasi berdasarkan data SIMULATED.",
[["Apakah reach tinggi membuktikan komunikasi efektif?","Tidak. Reach adalah output delivery; efektivitas perlu bukti perubahan pemahaman, persepsi, perilaku, atau outcome sesuai objective."],["Apa beda attribution dan incrementality?","Attribution membagi kredit menurut aturan model; incrementality mengestimasi tambahan outcome yang disebabkan aktivitas dibanding kondisi counterfactual."],["Mengapa learning agenda harus ditetapkan sebelum campaign?","Agar pengumpulan data, metode, sample, dan decision threshold sesuai pertanyaan; mengurangi bias memilih metrik setelah melihat hasil."]],
[["Output","Hasil distribusi seperti reach, impressions, views, frequency."],["Outtake","Respons audience seperti attention, recall, comprehension, consideration."],["Outcome","Perubahan perilaku/bisnis seperti trial, sales, lead, retention."],["Learning agenda","Daftar pertanyaan, hipotesis, metode, dan keputusan yang ingin diuji."]],"DPA-T02-CH09"),
G("Capstone Connection Strategy menggabungkan problem framing, insight, positioning, journey, channel roles, communication architecture, creative brief, orchestration, effectiveness, dan recommendation. Deck yang baik memperlihatkan logika dari evidence ke keputusan; bukan hanya moodboard atau channel list. Setiap asumsi, estimasi, dan data simulasi harus diberi label, serta rekomendasi perlu menyebut trade-off, owner, dan learning next step.",
"SIMULATED — brand consumer akan meluncurkan produk baru selama 90 hari. Capstone harus menunjukkan bagaimana audience discovery, proposition, creator, paid social, search, retail touchpoint, product page, dan CRM bekerja sebagai satu pengalaman, termasuk bagaimana hasilnya akan dievaluasi.",
["<b>Audit konsistensi.</b> Pastikan problem, insight, proposition, journey, message, channel, dan KPI saling menguatkan.","<b>Bangun recommendation.</b> Sajikan audience, experience architecture, investment implication, creative need, governance, dan risk.","<b>Simulasikan trade-off.</b> Bandingkan opsi dengan budget/timeline berbeda dan jelaskan konsekuensi.","<b>Presentasikan dan defend.</b> Jawab mengapa strategi dipilih, bukti apa yang mendukung, apa yang belum diketahui, dan kapan akan diubah."],
"Susun deck 10–12 slide dan workbook: brief, evidence log, audience/insight, positioning, journey, message house, channel-role matrix, creative brief, measurement/learning agenda, governance, budget implication, dan 30/60/90-day next steps. Labeli synthetic assumptions.",
[["Apa yang membedakan capstone strategis dari moodboard?","Capstone menunjukkan evidence, diagnosis, strategi, channel/message architecture, feasibility, KPI, governance, dan keputusan yang dapat dipertanggungjawabkan."],["Bagaimana menyampaikan uncertainty kepada klien?","Nyatakan assumption, confidence, data gap, sensitivity, dan cara mengujinya; jangan menyamarkan estimasi sebagai fakta."],["Apa ukuran recommendation siap dijalankan?","Ada owner, timeline, asset/approval requirements, budget implication, KPI, QA, risks, dan decision gates."]],
[["Strategic rationale","Alasan berbasis evidence mengapa strategi dipilih dibanding alternatif."],["Trade-off","Konsekuensi ketika memilih satu opsi dibanding opsi lain."],["Decision gate","Titik evaluasi untuk lanjut, ubah, atau hentikan aktivitas."],["Executive narrative","Alur komunikasi singkat yang menghubungkan masalah, evidence, keputusan, impact, dan risiko."]],"DPA-T02-CH10")
],
media:[
G("Media Planner menerjemahkan business dan communication objective menjadi media objective dan rencana yang dapat dibeli/dieksekusi. Brief harus mengunci target audience, geography, timing, product availability, budget, KPI, mandatories, competitive context, dan definisi sukses. Planner menanyakan hal yang belum jelas sebelum forecast, karena asumsi target, reach, atau conversion yang tidak terdefinisi akan membuat seluruh plan sulit dipertanggungjawabkan.",
"SIMULATED — klien meminta awareness nasional selama 8 minggu, tetapi budget hanya cukup untuk beberapa kota dan produk tidak tersedia merata. Planner harus mengklarifikasi priority market, distribution footprint, audience, dan peran reach vs frequency sebelum membuat plan.",
["<b>Terjemahkan objective.</b> Pisahkan business goal, communication task, media task, KPI, target, dan periode.","<b>Lengkapi requirement.</b> Catat target, geography, audience, brand safety, budget, campaign dates, asset, stock, dan approval.","<b>Uji feasibility.</b> Periksa apakah budget, inventory, timing, dan target masuk akal; dokumentasikan gap.","<b>Susun clarification log.</b> Tulis pertanyaan, assumption, owner, dan dampak bila jawabannya berubah."],
"Buat media brief intake dan assumption log satu campaign: objective tree, audience, target market, timeline, budget, KPI, mandatories, inventory dependencies, serta lima pertanyaan klarifikasi untuk klien.",
[["Apa beda business objective dan media objective?","Business objective adalah hasil bisnis; media objective adalah kontribusi distribusi/eksposur atau aksi media yang mendukung hasil tersebut."],["Mengapa distribution footprint harus dicek sebelum national reach plan?","Media dapat menjangkau wilayah tanpa produk/layanan tersedia; exposure tersebut membuang budget dan dapat merusak experience."],["Apa yang harus dilakukan ketika brief belum lengkap?","Catat gap, minta clarification, nyatakan asumsi sementara, dan jangan menyajikan forecast seolah-olah sudah pasti."]],
[["Media brief","Ringkasan tujuan, audience, budget, timing, KPI, dan constraint media."],["Media objective","Tugas media seperti reach, frequency, qualified traffic, atau conversion."],["Mandatories","Persyaratan wajib terkait brand, legal, market, atau campaign."],["Assumption log","Catatan asumsi, confidence, owner, dan dampak perubahan."]],"DPA-T03-CH01"),
G("Audience planning memilih siapa yang perlu dijangkau, di mana mereka berada, bagaimana konsumsi medianya, dan apakah data yang digunakan cukup relevan. Gunakan behavioral, category, contextual, first-party, survey, syndicated, dan platform data dengan memahami definisi serta bias masing-masing. Audience sizing perlu menyebut universe, target definition, duplication, geography, dan periode. Planner tidak boleh menganggap platform audience estimate sama dengan unique people.",
"SIMULATED — platform A melaporkan audience potential 5 juta, panel media menunjukkan 3,2 juta, dan CRM berisi 400 ribu pelanggan. Angka ini berbeda karena universe, identity, recency, deduplication, dan metodologi; tidak dapat langsung dijumlahkan.",
["<b>Definisikan audience universe.</b> Tentukan target, age/geography/context/behavior, exclusion, dan periode relevansi.","<b>Audit data sources.</b> Catat sample, methodology, update date, bias, match rate, dan coverage.","<b>Bandingkan media habits.</b> Hubungkan consumption occasion, device, platform, format, dan attention context.","<b>Terjemahkan ke planning implication.</b> Tentukan reach opportunity, overlap, audience priority, dan risk."],
"Buat audience landscape berisi 2–3 segmen, estimasi universe dengan source caveat, media consumption, occasion, platform role, duplication risk, dan implikasi terhadap channel selection.",
[["Mengapa audience estimate tidak bisa langsung dijumlahkan lintas platform?","Universe, identity resolution, time window, deduplication, dan metode pengukuran berbeda; hasilnya dapat overlap."],["Apa fungsi first-party data dalam media planning?","Membantu memahami existing customers/consented audience dan membangun targeting atau suppression, dengan governance serta izin yang sesuai."],["Mengapa data source harus punya tanggal dan metodologi?","Audience behavior dan platform definitions berubah; tanpa recency/method, planner tidak bisa menilai reliability estimate."]],
[["Universe","Populasi total yang menjadi dasar audience estimate."],["Duplication","Audience yang sama muncul pada lebih dari satu channel/source."],["Reach universe","Populasi target yang dapat dijangkau menurut definisi dan sumber tertentu."],["First-party data","Data yang diperoleh langsung dari interaksi dengan organisasi sesuai consent/legal basis."]],"DPA-T03-CH02"),
G("Media landscape evaluation menilai channel, format, placement, publisher, inventory quality, audience fit, environment, availability, cost model, dan measurement. Channel yang sama dapat memiliki kualitas berbeda menurut placement dan context. Planner perlu membedakan media owner/publisher, platform self-serve, network, DSP, dan reseller; pahami siapa mengontrol inventory, data, ad serving, brand safety, dan laporan delivery.",
"SIMULATED — dua publisher menawarkan audience profile yang mirip, tetapi Publisher A memiliki placement premium dengan viewability tinggi dan Publisher B memiliki low-cost inventory dengan data transparency terbatas. Keputusan tidak cukup membandingkan CPM.",
["<b>Inventarisasi opsi.</b> Catat channel, publisher, placement, format, buying method, availability, audience, dan geo.","<b>Nilai kualitas inventory.</b> Periksa context, viewability, IVT, brand safety, transparency, audience methodology, dan measurement coverage.","<b>Bandingkan cost apples-to-apples.</b> Samakan unit, deliverable, flight, currency, fee, added value, dan billable basis.","<b>Dokumentasikan suitability.</b> Nyatakan kapan inventory cocok/tidak cocok dan risiko supply."],
"Buat inventory evaluation sheet minimal enam opsi: audience fit, placement/context, buying type, rate basis, projected delivery, quality controls, reporting, exclusions, dan recommendation.",
[["Mengapa CPM murah belum tentu inventory bernilai?","Cost per thousand tidak mengukur viewability, IVT, contextual suitability, attention, audience relevance, atau outcomes."],["Apa beda publisher direct dan DSP inventory?","Direct dibeli melalui media owner/representative dengan terms spesifik; DSP mengakses inventory melalui platform dan mekanisme auction/deal."],["Apa yang dimaksud apples-to-apples media comparison?","Menyamakan scope, format, audience, dates, impressions/reach, fee, measurement, dan delivery terms sebelum membandingkan harga."]],
[["Inventory","Kesempatan/slot media yang tersedia untuk penayangan iklan."],["Media owner","Pihak yang memiliki atau mengelola media inventory."],["Viewability","Apakah impression memenuhi kriteria dapat terlihat sesuai standar yang dipakai."],["Billable basis","Definisi delivery yang menjadi dasar penagihan."]],"DPA-T03-CH03"),
G("Media objective dan KPI harus berasal dari funnel serta peran channel. Awareness dapat menggunakan reach, frequency, viewable impressions, atau brand metrics; consideration bisa menggunakan qualified visits/engagement; performance menggunakan conversion, CPA, atau revenue. KPI harus mempunyai formula, unit, denominator, source, attribution window, target, dan guardrail. Jangan mencampur metric platform yang tidak comparable tanpa normalisasi.",
"SIMULATED — campaign video mencapai 2 juta impressions tetapi hanya 45% eligible viewable impressions. Bila objective awareness dengan target viewability, KPI yang relevan bukan total impressions saja; bila objective action, perlu downstream site quality.",
["<b>Susun KPI hierarchy.</b> Tentukan business outcome, media primary KPI, diagnostic metrics, dan guardrails.","<b>Definisikan formula.</b> Catat numerator, denominator, unit, window, source, attribution rule, serta currency.","<b>Tetapkan target realistis.</b> Gunakan historical data/benchmark yang relevan dan jelaskan confidence.","<b>Rancang reporting.</b> Tentukan cadence, dimensions, owners, alert threshold, dan decision trigger."],
"Buat KPI dictionary untuk minimal enam media metric dan susun objective-to-KPI tree. Sertakan rumus, sumber, unit, target, guardrail, window, dan alasan pemilihan.",
[["Mengapa KPI perlu denominator dan window?","Tanpa denominator/periode yang jelas, angka tidak dapat dibandingkan dan dapat menyesatkan."],["Apa beda primary dan diagnostic metric?","Primary menentukan keberhasilan; diagnostic membantu menjelaskan penyebab perubahan primary metric."],["Mengapa CTR tidak boleh menjadi KPI universal?","CTR bergantung pada format, objective, placement, audience, dan click definition; ia tidak selalu mencerminkan business outcome."]],
[["Primary KPI","Metrik utama yang merepresentasikan objective."],["Diagnostic metric","Metrik pendukung untuk menjelaskan perubahan performa."],["Guardrail","Metrik pembatas agar optimasi tidak merusak kualitas/outcome lain."],["Attribution window","Periode ketika touchpoint dapat menerima credit atas conversion."]],"DPA-T03-CH04"),
G("Media mix mengalokasikan investasi antar channel dan format berdasarkan audience, task, reach/intent, cost, expected contribution, creative, measurement, dan risiko. Budget allocation bukan pembagian rata atau sekadar mengejar ROAS platform. Planner membuat scenario dan menjelaskan marginal trade-off: apa yang hilang ketika suatu channel dikurangi, dan apa yang diperoleh ketika budget dipindah. Forecast harus menampilkan input, range, dan uncertainty.",
"SIMULATED — budget Rp1 miliar dibagi ke Search, Social, Video, dan Publisher Direct. Menambah Search dapat meningkatkan intent capture tetapi memiliki volume terbatas; menambah Social/Video dapat memperluas demand dan branded search. Mix diuji dengan scenario, bukan dipastikan dari satu forecast.",
["<b>Tetapkan channel task.</b> Kaitkan setiap channel dengan journey dan outcome yang ditargetkan.","<b>Bangun allocation scenarios.</b> Buat conservative/base/stretch beserta assumptions, expected delivery, risk, dan trade-off.","<b>Periksa diminishing returns.</b> Nilai marginal cost, audience saturation, frequency, inventory limits, dan performance curve.","<b>Justifikasi rekomendasi.</b> Hubungkan alokasi dengan business objective, evidence, confidence, dan decision gates."],
"Buat tiga media-mix scenarios dengan budget total tetap. Untuk setiap skenario tulis allocation, KPI, forecast range, assumptions, risks, marginal trade-off, dan kondisi realokasi.",
[["Apa beda average ROAS dan marginal ROAS?","Average menilai hasil keseluruhan; marginal mengukur hasil tambahan dari satu unit budget berikutnya dan lebih relevan untuk scaling."],["Mengapa satu channel dengan ROAS tertinggi tidak otomatis menerima seluruh budget?","Volume, incrementality, role dalam demand creation, saturation, overlap, margin, dan channel risk dapat membuat return marginal turun."],["Apa yang wajib ada dalam forecast?","Input, formula, time window, range, source, confidence, scenario, serta penjelasan bahwa forecast bukan guaranteed delivery."]],
[["Media mix","Kombinasi channel, format, placement, dan investasi."],["Marginal return","Hasil tambahan dari tambahan satu unit resource/budget."],["Diminishing returns","Kondisi ketika tambahan spend memberi output/return yang makin kecil."],["Scenario planning","Perbandingan beberapa konfigurasi berdasarkan asumsi dan kondisi berbeda."]],"DPA-T03-CH05"),
G("Reach dan frequency mengukur distribusi kepada audience; CPM/CPC/CPP mengukur biaya menurut unit delivery; GRP/TRP mengukur tekanan iklan berdasarkan rating audience. Semua metrik bergantung pada universe, source, methodology, period, duplication, dan currency. Forecast perlu membedakan unique reach dengan impressions serta rata-rata frequency dengan distribusi frekuensi. Jangan membandingkan GRP, platform reach, dan panel estimates tanpa metodologi sepadan.",
"SIMULATED — plan memiliki 10 juta impressions untuk universe 2 juta orang. Frequency 5 hanya benar jika impressions dan unique reach menggunakan definisi, audience, serta periode yang sama; ia tidak menunjukkan distribusi individual yang merata.",
["<b>Tetapkan universe.</b> Nyatakan target population, geography, panel/platform source, dan period.","<b>Hitung cost metrics.</b> CPM, CPC, CPP, dan cost per reach dihitung dari unit serta delivery yang didefinisikan.","<b>Forecast reach/frequency.</b> Pertimbangkan duplication, overlap, inventory, exposure distribution, dan uncertainty.","<b>Bandingkan lintas media.</b> Catat metodologi TV/OOH/digital, rating source, audience base, dan caveat."],
"Buat media forecast dengan CPM, reach, frequency, GRP/TRP, dan CPP untuk skenario latihan. Tulis source/universe, formula, assumptions, duplication caveat, dan sensitivity saat reach turun.",
[["Apa beda impressions dan reach?","Impressions menghitung exposure; reach menghitung individu/household unik menurut metodologi yang digunakan."],["Apa arti GRP?","Gross Rating Points mengukur total rating points berdasarkan target universe; dapat mencakup repeated exposure."],["Mengapa platform reach tidak selalu dapat dijumlahkan lintas channel?","Setiap platform dapat menggunakan identity, deduplication, universe, dan time window berbeda."]],
[["Reach","Jumlah orang/household unik yang terpapar."],["Frequency","Rata-rata exposure per unit reach dalam periode."],["GRP/TRP","Gross/Target Rating Points sebagai ukuran tekanan media terhadap universe."],["CPP","Cost per rating point, biaya untuk satu rating point."]],"DPA-T03-CH06"),
G("Media flowchart menerjemahkan strategi dan budget menjadi jadwal, channel, format, weight, target, owner, dan flight dates. Pola continuity, flighting, dan pulsing berbeda sesuai seasonality, demand, launch moment, inventory, serta budget. Scenario planning menguji perubahan tanggal, stock, price promotion, atau media availability. Flowchart bukan dekorasi; ia menjadi alat koordinasi planning, buying, creative, client, dan finance.",
"SIMULATED — brand memiliki tiga burst penjualan dan satu periode low-demand. Continuity menjaga baseline presence, flighting memusatkan spend pada burst, sedangkan pulsing menggabungkan keduanya. Pilihan harus didukung sales calendar dan evidence demand.",
["<b>Bangun kalender.</b> Tentukan phase, date, channel, format, audience, weight, spend, objective, dan asset deadline.","<b>Pilih flighting logic.</b> Cocokkan continuity/pulsing/flighting dengan seasonality dan objective.","<b>Modelkan scenario.</b> Uji launch delay, budget cut, inventory shortage, dan creative readiness.","<b>Sinkronkan dependencies.</b> Tandai approval, publisher booking, trafficking, tracking, stock, serta owner."],
"Buat flowchart 8 minggu dengan channel/format, spend weighting, flighting, asset deadline, dependencies, dan three contingency scenarios. Tulis change-control rules jika dates atau inventory berubah.",
[["Apa risiko flighting tanpa stock calendar?","Iklan dapat mendorong demand saat produk tidak tersedia dan membuang budget atau menurunkan customer trust."],["Kapan pulsing lebih tepat daripada full continuity?","Saat baseline presence dibutuhkan tetapi demand/seasonality memiliki momen puncak yang memerlukan intensitas tambahan."],["Apa fungsi dependency mapping?","Memastikan booking, creative, approvals, tags, stock, dan owner siap sesuai urutan launch."]],
[["Flowchart","Visualisasi timing dan alokasi channel/format sepanjang campaign."],["Continuity","Penayangan relatif konsisten sepanjang periode."],["Pulsing","Kombinasi baseline presence dan burst intensity."],["Dependency","Prasyarat yang harus terpenuhi sebelum aktivitas dimulai."]],"DPA-T03-CH07"),
G("Buying brief adalah jembatan antara keputusan planner dan eksekusi media buyer/investment, bukan instruksi samar. Brief perlu memuat objective, target, channel role, budget, dates, format, audience, geography, KPI, benchmark, mandatory, exclusions, creative, measurement, dan approval. Planner juga memastikan rekomendasi commercial dari publisher/buyer dapat dibandingkan serta tetap sesuai rationale media plan.",
"SIMULATED — planner menyerahkan rencana video dengan budget dan target reach, tetapi tidak menyebut skippable/non-skippable, view definition, audience, placement exclusion, atau tracking. Buyer tidak bisa membooking dan mengukur dengan benar tanpa clarification.",
["<b>Terjemahkan plan ke brief.</b> Detailkan channel, inventory, format, audience, budget, dates, KPI, specs, tracking, dan constraints.","<b>Koordinasikan partner.</b> Minta availability, rate, delivery definition, measurement, value-add, cancellation, dan makegood terms.","<b>Bandingkan proposal.</b> Normalisasi rate, audience, formats, delivery, fee, bonus, dan quality assurance.","<b>Handoff dan sign-off.</b> Pastikan buyer, Ad Ops, creative, data, client, dan finance memahami owner dan acceptance criteria."],
"Buat buying brief, RFP question list, apples-to-apples proposal comparison, owner/RACI table, dan handoff checklist untuk satu digital + publisher package.",
[["Apa beda media planner dan media buyer?","Planner merancang channel/budget/forecast dan rationale; buyer melakukan negotiation, booking, buying terms, serta stewardship sesuai mandat."],["Mengapa rate card tidak cukup untuk menilai proposal?","Perlu delivery basis, audience, placement quality, fees, value-add, dates, measurement, cancellation, serta contractual makegood."],["Apa bukti buying handoff siap?","Buyer menerima brief final, inventory/format, budget/date, KPI, spec, tracking, approval, terms, dan escalation owner."]],
[["Buying brief","Instruksi operasional untuk membeli media sesuai media plan."],["RFP","Request for Proposal kepada media owner/vendor."],["Makegood","Kompensasi delivery yang kurang sesuai ketentuan kontrak."],["RACI","Pembagian accountable/responsible/consulted/informed."]],"DPA-T03-CH08"),
G("Post-campaign analysis membandingkan plan, booked, delivered, measured, dan billed results. Evaluasi memisahkan under/over-delivery, cost variance, audience quality, creative performance, reach/frequency, placement quality, outcomes, serta data limitations. Planner harus menjelaskan mengapa hasil berubah, apa bukti pendukung, apa faktor eksternal, dan apa yang direkomendasikan untuk flight berikutnya.",
"SIMULATED — campaign mencapai impressions 8% di bawah plan namun CPM 12% lebih rendah. Hasil tidak otomatis baik: reach mungkin turun, placement mungkin berbeda, atau frequency meningkat. Evaluasi harus mengecek audience, quality, cost, dan outcome bersama.",
["<b>Reconcile delivery.</b> Bandingkan planned/booked/delivered/billed dengan definisi dan cut-off yang sama.","<b>Diagnose variance.</b> Segmentasikan channel, placement, audience, date, creative, dan supply.","<b>Read effectiveness.</b> Hubungkan output media dengan site/brand/sales outcomes sambil membedakan attribution dan incrementality.","<b>Recommend next flight.</b> Tulis change, expected mechanism, impact, risk, owner, dan learning question."],
"Buat post-buy report berisi plan-vs-actual, reach/frequency, cost variance, placement quality, outcome, discrepancy note, root-cause hypothesis, dan tiga next-flight decisions.",
[["Mengapa CPM turun belum tentu kemenangan?","CPM lebih murah bisa disebabkan placement/audience quality menurun atau delivery bergeser; cek reach, attention, fraud, conversion, dan margin."],["Apa beda delivery analysis dan effectiveness analysis?","Delivery menilai pemenuhan media plan; effectiveness menilai perubahan audience/business outcome."],["Apa syarat rekomendasi optimization yang kuat?","Root cause evidence, change spesifik, expected mechanism, KPI/guardrail, owner, dan batas inferensi."]],
[["Post-buy","Evaluasi pembelian dan delivery setelah campaign."],["Variance","Perbedaan antara plan/target dan hasil aktual."],["Root-cause hypothesis","Dugaan penyebab perubahan yang perlu diuji dengan data."],["Effectiveness","Derajat tercapainya outcome yang ditetapkan."]],"DPA-T03-CH09"),
G("Capstone Media Planning harus memperlihatkan alur dari brief hingga rekomendasi post-buy. Nilai utama bukan banyaknya chart, tetapi konsistensi audience, role, budget, forecast, flighting, buying handoff, KPI, dan evaluasi. Setiap angka diberi sumber atau label SIMULATED. Planner perlu mampu menjelaskan trade-off antara reach, frequency, quality, cost, timing, serta business objective.",
"SIMULATED — brand FMCG ingin meluncurkan produk di 8 kota dengan budget 2 miliar rupiah selama 10 minggu. Tim harus memilih channel dan media owner, menyusun scenario, menetapkan reach goal, menyiapkan buying brief, serta merancang cara evaluasi.",
["<b>Integrasikan analysis.</b> Hubungkan brief, audience, media landscape, objective, KPI, dan channel roles.","<b>Susun plan dan forecast.</b> Buat budget, mix, reach/frequency, cost, flowchart, dan scenarios.","<b>Rancang execution governance.</b> Siapkan brief, owner, timeline, approvals, measurement, dan contingency.","<b>Present dan defend.</b> Jelaskan alasan, trade-off, assumptions, risks, dan post-buy learning."],
"Siapkan media plan 10 slide plus workbook: brief, audience, inventory evaluation, channel roles, budget scenarios, reach/frequency forecast, flowchart, buying brief, KPI dashboard specification, post-buy evaluation plan, dan assumptions log.",
[["Apa yang membuat media plan dapat dipertanggungjawabkan?","Setiap keputusan terkait audience, task, inventory, budget, forecast, KPI, dan timing memiliki rationale serta sumber/asumsi."],["Mengapa forecast perlu scenario range?","Inventory, audience, price, competition, creative readiness, dan response tidak pasti; satu angka tunggal memberi kepastian palsu."],["Apa yang harus disiapkan untuk presentasi klien?","Recommendation, logic, budget, KPI, timing, risks, assumptions, dependencies, owner, dan keputusan yang diminta."]],
[["Media rationale","Alasan audience/channel/inventory dan investasi dipilih."],["Sensitivity analysis","Uji bagaimana hasil berubah saat input/asumsi berubah."],["Post-buy recommendation","Keputusan perubahan media berdasarkan hasil setelah campaign."],["Investment trade-off","Konsekuensi antar outcome saat memilih alokasi investasi."]],"DPA-T03-CH10")
],
paidsearch:[
G("Paid Search menangkap intent yang diekspresikan melalui query. Specialist harus memahami auction eligibility, Ad Rank, keyword/query, ad relevance, landing experience, conversion signal, bidding, dan budget. Search term bukan keyword target; platform dapat mencocokkan query melalui variasi. Performance dinilai dari kualitas demand dan kontribusi bisnis, bukan hanya klik atau impression.",
"SIMULATED — keyword broad 'asuransi mobil' menghasilkan 2.000 klik, tetapi banyak search term mencari pekerjaan dan definisi. Negative keyword dan landing page intent match memperbaiki kualitas traffic meski volume klik turun.",
["<b>Pahami auction.</b> Pelajari eligibility, Ad Rank, bid, quality/relevance signals, budget, dan auction insights.","<b>Audit search intent.</b> Kelompokkan query informational, commercial, transactional, branded, competitor, dan local.","<b>Definisikan conversion.</b> Bedakan primary conversion, micro-conversion, value, attribution window, dan offline outcome.","<b>Hubungkan intent ke landing page.</b> Pastikan ad promise dan page content menjawab query yang sama."],
"Buat search ecosystem map untuk satu kategori: query types, auction factors, account actors, conversion actions, landing-page match, dan KPI chain. Gunakan sample query nyata atau label SIMULATED.",
[["Mengapa search bukan sekadar bidding keyword?","Auction, query intent, relevance, landing experience, conversion signal, budget, dan competition bersama-sama menentukan delivery serta outcome."],["Apa perbedaan keyword dengan search term?","Keyword adalah target/setting yang dipilih advertiser; search term adalah query aktual yang memicu iklan."],["Mengapa conversion harus didefinisikan sebelum campaign?","Bidding dan reporting belajar dari conversion signal; event yang salah mengarahkan algoritma serta keputusan budget ke outcome yang keliru."]],
[["Ad Rank","Sistem penentuan eligibility/position yang menggunakan bid, quality, context, dan auction factors."],["Search term","Query aktual yang diketik/diekspresikan pengguna."],["Search intent","Tujuan atau kebutuhan di balik query."],["Primary conversion","Tindakan utama yang merepresentasikan nilai campaign."]],"DPA-T04-CH01"),
G("Keyword research menyusun peluang query berdasarkan intent, relevance, volume, competition, value, geography, seasonality, dan landing-page readiness. Search volume tidak sama dengan demand yang dapat dikonversi; keyword populer bisa tidak relevan, terlalu luas, atau punya economics buruk. Competitor ad research membantu melihat positioning dan SERP, tetapi tidak membuktikan biaya atau profit pesaing.",
"SIMULATED — keyword 'kursus digital marketing' memiliki volume tinggi, namun target course berbayar untuk profesional mungkin lebih cocok dengan query 'sertifikasi digital marketing untuk karyawan'. Intent dan willingness-to-pay berbeda.",
["<b>Mulai dari seed.</b> Turunkan produk, need, category terms, problems, brands, locations, dan language variants.","<b>Kelompokkan intent.</b> Tandai informational/commercial/transactional, urgency, audience fit, dan funnel stage.","<b>Nilai economics.</b> Perkirakan CPC, conversion likelihood, margin/value, search volume, dan competition; jangan menganggap tools sebagai ground truth.","<b>Bangun keyword-to-page map.</b> Tentukan landing destination, message, negative risk, dan priority."],
"Buat 30-keyword intent map dengan cluster, priority, expected query type, CPC/volume source, landing page, negative candidates, dan assumptions. Buat competitor SERP review untuk tiga query utama.",
[["Mengapa volume tinggi tidak selalu berarti prioritas tinggi?","Volume tanpa intent, conversion potential, margin, landing fit, dan economics bisa menghasilkan traffic mahal tetapi tidak bernilai."],["Bagaimana mengelompokkan keyword?","Berdasarkan intent, product/service, need, brand, competitor, geography, dan funnel context."],["Apa batas competitor ad analysis?","Ad copy/visibility adalah observasi; tidak memberi akses ke bid, actual CPA, margin, atau conversion results pesaing."]],
[["Seed keyword","Istilah awal untuk memperluas riset query."],["Keyword cluster","Kelompok query dengan intent/topik yang saling terkait."],["Commercial intent","Query yang menunjukkan riset atau perbandingan sebelum pembelian."],["SERP","Search Engine Results Page, halaman hasil pencarian."]],"DPA-T04-CH02"),
G("Campaign architecture mengatur hubungan account, campaign, ad group, keyword, ads, assets, audience, geography, language, budget, conversion action, dan landing page. Struktur yang baik memberi kontrol cukup tanpa memecah data terlalu kecil. Naming taxonomy memudahkan QA dan reporting; pemilihan campaign type harus mengikuti objective, channel inventory, feed, conversion readiness, dan kemampuan kontrol.",
"SIMULATED — satu campaign terlalu banyak menggabungkan branded, generic, dan competitor terms sehingga budget generic terserap brand traffic. Pemisahan diperlukan untuk visibility dan budget control, tetapi membagi setiap keyword ke campaign sendiri akan memfragmentasi learning.",
["<b>Definisikan boundaries.</b> Pisahkan brand/non-brand, geography, product line, language, objective, budget, atau intent jika ada alasan operasional.","<b>Susun ad group.</b> Kelompokkan theme dengan ad relevance dan page fit; hindari satu ad group terlalu luas atau terlalu sempit.","<b>Rancang naming.</b> Gunakan brand_market_objective_campaign_type_product_audience_version.","<b>Validasi architecture.</b> Periksa negative overlap, budget control, conversion settings, asset compatibility, dan reporting."],
"Bangun account map untuk brand latihan: account settings, 3 campaign, ad groups, keyword clusters, ad assets, landing pages, conversion actions, naming, dan QA checks. Jelaskan alasan struktur.",
[["Mengapa tidak membuat satu campaign untuk setiap keyword?","Fragmentasi dapat membagi budget/conversion signals dan membuat learning serta management tidak efisien."],["Kapan campaign perlu dipisah?","Saat objective, budget, geo, product economics, brand protection, atau bidding strategy membutuhkan kontrol berbeda."],["Apa tujuan naming taxonomy?","Menjamin identifikasi objek, konsistensi laporan, QA, perubahan, dan handover antar operator."]],
[["Campaign","Unit pengelolaan objective/budget/settings."],["Ad group","Kelompok keyword/ads bertema tertentu dalam campaign."],["Naming taxonomy","Aturan penamaan objek yang konsisten."],["Negative overlap","Situasi keyword/negative settings saling menghalangi traffic yang seharusnya diterima."]],"DPA-T04-CH03"),
G("Match type mengatur seberapa luas keyword dapat mencocokkan query, tetapi tidak boleh dianggap sebagai exact string match sederhana. Search terms report menunjukkan query yang benar-benar memicu iklan dan menjadi sumber optimasi. Negative keyword melindungi relevance, budget, brand safety, serta query intent. Pemilihan negatives harus hati-hati agar tidak memblokir query bernilai.",
"SIMULATED — broad match 'software payroll' memicu query 'contoh slip gaji' dan 'lowongan HR'. Sebagian dapat relevan untuk konten, tetapi tidak untuk sales demo. Negative harus dipilih berdasarkan objective, bukan hanya karena query tidak identik.",
["<b>Pahami matching behavior.</b> Pelajari broad/phrase/exact menurut dokumentasi terkini serta sinyal intent/close variants.","<b>Audit search terms.</b> Kategorikan relevant, irrelevant, ambiguous, competitor, informational, dan conversion quality.","<b>Bangun negative taxonomy.</b> Bedakan account/campaign/ad-group negatives, brand exclusions, job-seeker, free-only, dan non-market terms.","<b>Review secara berulang.</b> Periksa query volume, spend, conversion quality, false blocking, dan perubahan behavior."],
"Buat search-term mining worksheet dari data latihan minimal 100 rows: intent, relevance, cost, conversions, value, action (keep/negative/observe), rationale, serta owner/date. Tulis daftar negative beserta risiko false positive.",
[["Apa fungsi search terms report?","Menunjukkan query yang memicu iklan untuk menilai intent, relevansi, biaya, conversion quality, dan peluang keyword/negative."],["Apa risiko negative keyword terlalu agresif?","Query bernilai dapat terblokir sehingga reach, volume, dan learning berkurang."],["Mengapa match type harus dicek di dokumentasi terbaru?","Platform mengubah matching behavior dan close variants; label match tidak selalu berarti literal match."]],
[["Match type","Aturan kedekatan/intent yang menentukan query eligibility."],["Negative keyword","Istilah yang mengecualikan query sesuai scope setting."],["Search terms report","Laporan query aktual yang memicu iklan."],["False positive exclusion","Negative yang salah mengecualikan pencarian bernilai."]],"DPA-T04-CH04"),
G("Search ad copy harus menjawab query, menyampaikan benefit, memberi proof, dan mengarahkan ke landing page yang sesuai. Responsive Search Ads menguji kombinasi headline/description; assets menambah informasi dan action. Message match mengurangi cognitive friction: kata, offer, price, eligibility, dan CTA pada iklan harus selaras dengan destination page. Klaim harus dapat dibuktikan dan sesuai policy.",
"SIMULATED — iklan menjanjikan 'gratis konsultasi hari ini' tetapi landing page meminta pembayaran dan jadwal minggu depan. CTR bisa tinggi karena janji menarik, tetapi conversion jatuh dan trust rusak.",
["<b>Rumuskan message angle.</b> Gunakan search intent, differentiator, benefit, proof, objection, dan CTA.","<b>Bangun asset set.</b> Tulis headlines/descriptions yang saling melengkapi, hindari repetisi dan unsupported claims.","<b>Audit extensions/assets.</b> Periksa sitelinks, callouts, snippets, image/call assets bila tersedia dan relevan.","<b>QA landing page.</b> Cocokkan offer, page title, speed, mobile usability, form, legal text, and conversion path."],
"Buat dua RSA concept untuk satu ad group: masing-masing 10–15 headline draft, empat description, assets, keyword theme, LP URL, proof requirement, dan policy checklist. Tandai klaim yang memerlukan substantiation.",
[["Apa yang dimaksud message match?","Konsistensi antara query, ad promise, offer, dan konten landing page sehingga audience menemukan yang dijanjikan."],["Mengapa semua headline tidak harus memiliki CTA yang sama?","Asset perlu melengkapi benefit, proof, offer, dan action; repetisi mengurangi kombinasi informasi yang tersedia."],["Apa yang dilakukan jika CTR naik tetapi CVR turun?","Audit query mix, promise-to-page match, audience quality, page experience, offer, dan tracking sebelum menyimpulkan creative lebih baik."]],
[["RSA","Responsive Search Ad yang mengombinasikan asset teks berdasarkan auction/context."],["Ad assets","Informasi atau format tambahan yang memperkaya iklan."],["Message match","Kesesuaian query/ad message dengan landing page."],["Substantiation","Bukti yang mendukung klaim advertising."]],"DPA-T04-CH05"),
G("Bidding dan budget menentukan cara platform berpartisipasi dalam auction dan mengejar conversion/value. Manual, Maximize Clicks, Maximize Conversions, target CPA, Maximize Conversion Value, dan target ROAS memiliki kebutuhan sinyal serta trade-off berbeda. Smart bidding memerlukan conversion tracking yang sehat, volume yang memadai, dan definisi value yang tepat. Budget pacing harus dipantau bersama spend, impression share, marginal CPA/ROAS, dan business margin.",
"SIMULATED — target tROAS ditetapkan terlalu tinggi untuk akun baru tanpa conversion history. Delivery menjadi terbatas. Sebelum melonggarkan target, tim harus memvalidasi purchase event, value, bidding objective, budget, query mix, dan landing-page experience.",
["<b>Pilih strategy sesuai goal.</b> Tentukan click, lead, purchase, value, impression share, atau reach objective.","<b>Periksa signal readiness.</b> Validasi conversion action, volume, value, consent, deduplication, dan attribution window.","<b>Set budget/pacing guardrails.</b> Pantau daily spend, budget limited, lost IS, CPA/value, margin, dan seasonality.","<b>Ubah secara terkendali.</b> Catat baseline, change, expected effect, observation window, rollback/decision criteria."],
"Simulasikan tiga bid strategies untuk satu campaign. Isi input signal, required data, budget, expected trade-off, monitoring metrics, guardrail, dan perubahan yang dilakukan pada kasus underdelivery/overspend.",
[["Mengapa smart bidding tidak memperbaiki conversion tracking yang rusak?","Algoritma mengoptimalkan signal yang diberikan; event salah/duplikat membuat learning dan budget allocation ikut salah."],["Apa risiko menetapkan target ROAS terlalu tinggi?","Delivery dapat menyempit atau berhenti mengejar peluang yang masih profitable pada target bisnis sebenarnya."],["Apa yang dipantau selain average CPA?","Conversion value, margin, volume, query quality, impression share, budget pacing, new-customer share, dan marginal performance."]],
[["Smart bidding","Strategi bid otomatis yang mengoptimalkan outcome berdasarkan signals."],["tCPA","Target cost per acquisition."],["tROAS","Target return on ad spend berdasarkan conversion value."],["Impression share","Porsi eligible impressions yang berhasil dimenangkan."]],"DPA-T04-CH06"),
G("Conversion tracking mengubah business action menjadi signal yang dapat diukur dan dipakai bidding. Specialist harus membedakan page view, form submit, qualified lead, purchase, phone call, offline conversion, enhanced conversions, dan imported CRM outcomes. Event definition, count setting, value, attribution window, consent, deduplication, tag implementation, dan QA wajib disepakati sebelum optimasi.",
"SIMULATED — form submit dihitung sebagai primary conversion, tetapi 40% leads adalah spam/duplikat dan sales qualified rate rendah. Bidding mengejar form volume, bukan pipeline value. CRM qualification/offline conversion perlu dikirim secara tepat dengan governance.",
["<b>Definisikan action.</b> Pilih primary/secondary, counting method, value, source, owner, dan window.","<b>Map implementation.</b> Tetapkan tag/event, trigger, parameter, consent, enhanced/offline conversion flow, serta deduplication.","<b>QA event.</b> Uji expected vs actual, duplicates, missing values, cross-domain/redirect, mobile, and consent states.","<b>Reconcile business outcomes.</b> Cocokkan platform conversions dengan CRM/sales/revenue dan catat delay/attribution differences."],
"Buat conversion measurement spec untuk lead dan purchase: event name, trigger, parameters/value, tag owner, source of truth, consent, deduplication, QA test, offline import field, dan reconciliation plan.",
[["Mengapa form submit belum tentu qualified lead?","Submit hanya perilaku awal; qualification memerlukan validasi data, fit, sales response, dan outcome CRM."],["Apa risiko conversion double-counting?","Bidding/reporting menganggap conversion lebih banyak sehingga CPA/ROAS dan optimasi menjadi bias."],["Apa fungsi offline conversion import?","Menghubungkan conversion yang terjadi di CRM/sales setelah click dengan campaign signal, sesuai identifier, privacy, dan rules."]],
[["Conversion action","Tindakan yang ditetapkan sebagai outcome terukur."],["Enhanced conversions","Mekanisme matching conversion menggunakan data first-party yang di-hash sesuai ketentuan."],["Offline conversion","Outcome terjadi di luar website/platform, misalnya qualified sale."],["Deduplication","Pencegahan satu outcome tercatat lebih dari sekali."]],"DPA-T04-CH07"),
G("Diagnosis Search menggunakan search terms, auction insights, Quality Score components, impression share, landing-page signals, conversion rate, dan value. Quality Score adalah diagnostic indicator, bukan KPI bisnis atau tombol optimasi tunggal. Lost impression share karena budget berbeda dari rank. Analyst harus memisahkan issue query, competition, bid, relevance, page, tracking, dan budget sebelum membuat perubahan.",
"SIMULATED — campaign kehilangan impression share 25% karena rank, sementara budget tidak habis. Menambah budget bukan solusi utama; perlu mengecek bid strategy, ad relevance, expected CTR, landing experience, dan query relevance.",
["<b>Segmentasikan hasil.</b> Periksa brand/generic, query theme, device, geo, audience, hour, ad group, landing page, dan network.","<b>Diagnosis auction.</b> Pisahkan lost IS budget vs rank; cek competition dan bid eligibility.","<b>Uji relevance.</b> Review query-to-keyword, ad, landing page, conversion signal, dan user experience.","<b>Prioritaskan tindakan.</b> Dampak, confidence, effort, dependency, dan guardrail menentukan urutan."],
"Buat weekly search diagnosis report dengan segmentation, search term issues, lost IS, Quality Score components, LP issue, tracking check, root-cause hypotheses, prioritized actions, owner, dan follow-up date.",
[["Apakah Quality Score dapat menjadi business KPI?","Tidak. Ia diagnostic indicator untuk relevance/auction context; success harus dilihat pada cost, qualified conversion, value, dan margin."],["Apa beda lost IS budget dan lost IS rank?","Budget loss menunjukkan batas anggaran; rank loss berkaitan competitiveness/Ad Rank, bid, relevance, dan auction context."],["Mengapa diagnosis harus disegmentasi?","Rata-rata account dapat menutupi query, device, region, atau landing-page pockets yang punya masalah berbeda."]],
[["Quality Score","Indikator diagnostik kualitas/relevance pada keyword."],["Lost IS (budget)","Porsi eligible impressions hilang akibat keterbatasan budget."],["Lost IS (rank)","Porsi eligible impressions hilang akibat Ad Rank/competitiveness."],["Auction insights","Laporan kompetisi auction pada ruang dan waktu tertentu."]],"DPA-T04-CH08"),
G("Testing Search harus menguji satu hipotesis yang dapat dipisahkan dari perubahan lain. Variabel dapat berupa message angle, asset, landing page, match coverage, bid strategy, atau audience; test perlu primary metric, guardrail, randomization/experiment setup, sample/duration, seasonality control, dan stopping rule. Setelah test, interpretasikan effect size dan uncertainty, bukan hanya siapa yang tampak menang.",
"SIMULATED — dua RSA diluncurkan bersamaan dengan perubahan bidding dan LP. Conversion naik, tetapi tim tidak dapat mengidentifikasi penyebab. Test berikutnya mengisolasi creative angle sambil menjaga budget, targeting, dan page tetap stabil.",
["<b>Tulis hipotesis.</b> Hubungkan observation, change, audience, expected mechanism, primary KPI, dan guardrail.","<b>Rancang experiment.</b> Tentukan control/treatment, randomization, split, time, sample, seasonality, dan contamination risks.","<b>Jalankan QA.</b> Pastikan URLs, assets, conversion, budgets, and settings seimbang.","<b>Interpretasikan.</b> Baca uncertainty, volume, segment effects, business value, dan keputusan scale/iterate/stop."],
"Buat experiment backlog tiga test untuk Search: ad-message test, LP test, dan match/negative strategy test. Untuk satu test, lengkapi protocol, sample/duration assumptions, guardrails, QA, decision rule, dan results template.",
[["Mengapa perubahan banyak variabel sekaligus berbahaya?","Penyebab hasil tidak dapat diisolasi, sehingga tim tidak tahu intervensi mana yang memberi dampak."],["Apa arti hasil inconclusive?","Bukti belum cukup untuk memilih pemenang; itu bukan bukti bahwa variasi identik."],["Kapan eksperimen sebaiknya dihentikan?","Sesuai pre-defined stopping rule, misalnya safety issue, tracking failure, budget limit, atau sample/time threshold—bukan saat hasil disukai."]],
[["Hypothesis","Pernyataan evidence-to-change-to-outcome yang bisa diuji."],["Control/treatment","Kondisi pembanding dan variasi dalam experiment."],["Guardrail metric","Metrik yang membatasi efek samping optimasi."],["Effect size","Besarnya perubahan hasil yang diobservasi."]],"DPA-T04-CH09"),
G("Capstone Paid Search menguji kemampuan mengelola jalur dari intent sampai conversion dan diagnosis. Paket kerja harus menyatukan keyword architecture, campaign build, RSA/assets, bidding/budget, conversion tracking, negative strategy, QA, reporting, dan optimization. Semua forecast atau data yang tidak berasal dari account aktual wajib ditandai SIMULATED. Hasil harus dijelaskan menurut intent dan economics, bukan hanya platform metrics.",
"SIMULATED — perusahaan SaaS B2B ingin menghasilkan demo request. Tim harus memisahkan branded/generic/competitor, menjaga query quality, menghubungkan form dengan qualification CRM, dan menilai biaya per qualified demo.",
["<b>Frame brief.</b> Tentukan business goal, target market, proposition, economics, lead quality, and constraints.","<b>Build campaign.</b> Susun keyword, architecture, ads/assets, landing pages, bids, budgets, and tracking.","<b>QA dan monitor.</b> Simpan test evidence, change log, delivery, query mining, and conversion reconciliation.","<b>Present insight.</b> Jelaskan what changed, why, impact, uncertainty, recommendation, and next tests."],
"Bangun Search case-study workbook: brief, intent map 30 keywords, architecture, RSA assets, negative list, bid/budget scenario, conversion spec, QA log, weekly report, 3 optimizations, dan executive summary.",
[["Apa yang membuat paid search capstone berbeda dari kumpulan keyword?","Ia membuktikan intent-to-conversion system, termasuk architecture, message match, economics, tracking, optimization, dan QA."],["Mengapa qualified lead lebih bernilai daripada raw form volume?","Qualified lead lebih dekat ke pipeline/revenue; raw form dapat dipenuhi spam atau audience yang tidak sesuai."],["Bagaimana membedakan actual dan simulated result di portfolio?","Gunakan label jelas, jelaskan sumber/rumus, jangan klaim client spend atau campaign outcome yang tidak pernah terjadi."]],
[["Search architecture","Rancangan account/campaign/ad group/keyword/asset/LP."],["Qualified lead","Prospect yang memenuhi definisi sales/fit yang disepakati."],["Optimization log","Catatan perubahan, alasan, expected effect, dan hasil evaluasi."],["Search capstone","Paket bukti end-to-end yang mengintegrasikan intent, campaign, tracking, dan diagnosis."]],"DPA-T04-CH10")
],
programmatic:[
G("Programmatic adalah pembelian inventory digital melalui platform dan automation, bukan nama lain untuk semua paid media. Ekosistem mencakup advertiser/agency, DSP, ad exchange, SSP, publisher/ad server, data/identity partners, dan verification. Setiap pihak memiliki peran dalam auction, targeting, delivery, measurement, dan biaya. Trader harus memahami supply chain untuk membaca fees, latency, quality, transparency, dan accountability.",
"SIMULATED — advertiser membeli 10 juta impressions melalui DSP. Bid request melewati exchange dan SSP sebelum publisher ad server; beberapa intermediary menambah fee dan memengaruhi latency. Trader harus mengetahui supply path dan net media cost, bukan hanya CPM di UI DSP.",
["<b>Gambar supply chain.</b> Petakan advertiser, agency, DSP, exchange, SSP, publisher, ad server, data, measurement, dan billing.","<b>Bedakan ownership.</b> Tandai siapa mengelola demand, supply, auction, creative, identity, dan measurement.","<b>Map cost path.</b> Pisahkan media cost, platform fee, data fee, verification, agency fee, dan publisher take rate.","<b>Hubungkan ke workflow.</b> Ikuti brief hingga setup, auction, delivery, QA, report, dan invoice."],
"Buat programmatic ecosystem diagram dan cost-flow workbook untuk satu campaign. Sertakan owner, object, data/signal, fee layer, risk, dan kontrol pada setiap node.",
[["Apa perbedaan DSP dan SSP?","DSP membantu advertiser membeli inventory; SSP membantu publisher mengelola dan menjual inventory."],["Mengapa programmatic tidak sama dengan paid social?","Programmatic membeli inventory lintas publisher melalui DSP/exchange; paid social berjalan pada platform social dengan inventory/audience system masing-masing."],["Mengapa supply-chain transparency penting?","Intermediary fees, reselling, unauthorized supply, dan poor-quality inventory dapat mengurangi net value dan accountability."]],
[["DSP","Demand-Side Platform untuk mengelola pembelian media."],["SSP","Supply-Side Platform untuk mengelola penjualan inventory publisher."],["Ad exchange","Marketplace/auction layer yang menghubungkan demand dan supply."],["Ad server","Sistem untuk mengatur ad decisioning/delivery serta tracking."]],"DPA-T06-CH01"),
G("OpenRTB dan auction mechanics menjelaskan bagaimana bid request, impression opportunity, buyer response, price, dan creative diproses. Supply path menentukan rantai pihak yang terlibat dari publisher menuju DSP. Trader perlu memahami auction type, bid floor, timeout, win rate, clearing dynamics, deal identifiers, reseller, dan ads.txt/sellers.json sebagai sinyal otorisasi. Tidak semua mekanisme lelang bersifat first-price dengan implementasi identik.",
"SIMULATED — bid request tidak menghasilkan response karena timeout dan mismatch format. Campaign underspends meski bid tinggi. Diagnosis harus memeriksa deal eligibility, bid floor, supply path, creative spec, latency, dan targeting.",
["<b>Pelajari request-response.</b> Identifikasi impression, bid request, seat, device, user/context signals, bid response, creative, dan win/loss.","<b>Bedakan auction/deal.</b> Pahami open auction, private auction/PMP, preferred deal, dan programmatic guaranteed.","<b>Audit supply path.</b> Periksa seller authorization, direct/reseller, fees, duplicates, and inventory origin.","<b>Diagnosis auction.</b> Analisis floor, timeout, bid rate, win rate, clearing price, and eligibility."],
"Buat bid-flow diagram dan supply-path audit untuk dua inventory scenarios. Isi request signals, eligibility, auction/deal type, fee layers, authorized sellers checks, timeout risk, dan optimization actions.",
[["Apa itu bid floor?","Harga minimum yang disyaratkan supply side untuk eligible impression/deal."],["Apa fungsi ads.txt dan sellers.json?","Membantu transparansi dan otorisasi penjual inventory, tetapi tidak sendirian menjamin kualitas."],["Mengapa bid tinggi tidak menjamin win?","Eligibility, deal rules, timeout, floor, auction competition, creative compatibility, dan supply signals juga menentukan."]],
[["OpenRTB","Protokol standar untuk komunikasi transaksi RTB."],["Supply path","Rantai perantara yang dilalui inventory dari publisher ke buyer."],["Bid floor","Batas minimum harga bid yang diminta supply."],["PMP","Private Marketplace dengan akses/ketentuan deal yang dibatasi."]],"DPA-T06-CH02"),
G("Audience strategy programmatic menggabungkan first-party data, contextual, publisher segments, third-party data, identity solutions, dan privacy/consent. Audience targeting harus sesuai objective dan data rights. Cookie deprecation, browser restrictions, consent, match rates, data provenance, and identity interoperability dapat memengaruhi scale serta accuracy. Contextual targeting tidak sama dengan behavioral identity targeting.",
"SIMULATED — audience CRM seed match 35% pada DSP. Angka ini tidak berarti 65% audience tidak relevan; identity graph, formatting, consent, and addressability membatasi match. Tim perlu membandingkan contextual alternative dan reach loss.",
["<b>Definisikan audience use case.</b> Akuisisi, prospecting, suppression, retargeting, contextual reach, atau frequency control.","<b>Audit data provenance.</b> Catat source, consent, collection purpose, freshness, match method, geography, and usage rights.","<b>Nilai identity coverage.</b> Periksa match rate, device coverage, duplication, exclusions, and loss of addressability.","<b>Rancang privacy-safe alternatives.</b> Gunakan contextual, publisher first-party, cohort/aggregate, and modeled signals sesuai policy."],
"Buat audience decision matrix: first-party, contextual, publisher, and third-party options. Sertakan reach/match assumption, consent basis, quality risks, freshness, cost, and use-case fit.",
[["Apa beda first-party audience dan third-party data?","First-party berasal dari hubungan/interaksi langsung organisasi; third-party diperoleh dari sumber/pihak eksternal dengan ketentuan penggunaan."],["Mengapa match rate bukan audience quality?","Match rate hanya menunjukkan keberhasilan matching; tidak membuktikan intent, freshness, identity accuracy, atau conversion likelihood."],["Kapan contextual targeting lebih tepat?","Ketika page/content context relevan dan identity/consent constraints membatasi behavioral targeting, dengan QA brand suitability."]],
[["First-party data","Data yang dikumpulkan langsung oleh organisasi."],["Contextual targeting","Targeting berdasarkan konteks konten/halaman, bukan identity behavior."],["Identity resolution","Pengaitan identitas/signal lintas perangkat atau source dengan metode tertentu."],["Data provenance","Asal, metode pengumpulan, dan hak penggunaan data."]],"DPA-T06-CH03"),
G("Inventory mencakup format, device, environment, publisher, geo, audience, placement, viewability, fraud risk, and suitability. Deal types memberi tingkat kontrol dan komitmen berbeda. Trader perlu menilai inventory fit, scale, measurement eligibility, creative constraints, and cost. CTV, audio, video, display, native, in-app, DOOH, and mobile web memiliki kebutuhan asset, verification, and measurement berbeda.",
"SIMULATED — brand finance tidak cocok ditempatkan pada open exchange tanpa context controls; premium finance publisher memberikan relevansi lebih baik tetapi scale lebih kecil. Mix dapat menggabungkan contextual/PMP dengan open auction yang diverifikasi.",
["<b>Klasifikasikan inventory.</b> Map format, device, environment, publisher, geography, placement, and audience.","<b>Nilai suitability.</b> Periksa brand safety, category exclusions, content adjacency, IVT, viewability, and transparency.","<b>Pilih deal type.</b> Cocokkan reach/control/price/guarantee dengan campaign goal.","<b>Validasi creative compatibility.</b> Cek dimensions, ratio, duration, codec, click behavior, audio, and fallback."],
"Buat inventory matrix minimal enam opsi (display, video, CTV, audio, native, in-app atau DOOH) dengan format specs, deal type, audience, quality checks, cost assumptions, and use-case rationale.",
[["Apa beda brand safety dan brand suitability?","Safety menghindari konten yang jelas berbahaya; suitability menilai kesesuaian konteks dengan brand/category tolerance."],["Apa perbedaan PMP dan programmatic guaranteed?","PMP biasanya private auction access; programmatic guaranteed memiliki komitmen inventory/price/delivery yang disepakati."],["Mengapa format harus divalidasi sebelum buying?","Format incompatibility dapat menyebabkan rejection, rendering error, underdelivery, atau pengalaman iklan buruk."]],
[["Inventory","Placement/opportunity yang tersedia untuk dibeli."],["PMP","Private Marketplace/deal dengan akses tertentu."],["Programmatic Guaranteed","Pembelian terprogram dengan komitmen delivery yang disepakati."],["Suitability","Kesesuaian context/placement dengan toleransi brand."]],"DPA-T06-CH04"),
G("DSP navigation dimulai dengan memahami hirarki advertiser, campaign, insertion order/order, line item, targeting, creative, budget, flight, frequency, and optimization. Nomenclature antar-DSP berbeda; prinsip dasarnya tetap sama. DV360 menjadi platform utama belajar di roadmap, sedangkan The Trade Desk dan Amazon DSP dibandingkan pada capability serta inventory ecosystem. Tool access bergantung pada organisasi/partner dan tidak boleh dijanjikan hanya dari kursus.",
"SIMULATED — trader membuat line item dengan wrong exchange/format targeting sehingga budget tidak deliver. Setup perlu dikontrol melalui campaign map, naming, deal/creative compatibility, audience, and QA before activation.",
["<b>Kenali hierarchy.</b> Petakan advertiser/campaign/order/line item/creative/deal sesuai platform.","<b>Konfigurasi campaign.</b> Set objective, flight, budget, bid, geo, audience, frequency, inventory, and conversion signals.","<b>Kelola naming dan permissions.</b> Gunakan taxonomy, role access, approval, and change log.","<b>Verifikasi platform access.</b> Bedakan credential, demo/sandbox, partner seat, managed access, dan live buying permissions."],
"Buat DSP setup workbook untuk satu campaign: object hierarchy, naming, budgets, bids, audiences, inventory/deals, creatives, tracking, permissions, launch checklist, and monitoring cadence.",
[["Mengapa platform interface skills tidak cukup?","Trader harus memahami auction, supply, data, economics, verification, measurement, dan troubleshooting di balik kontrol UI."],["Apa beda line item dengan creative?","Line item mengatur delivery, targeting, bid, budget, dan schedule; creative adalah asset yang ditayangkan."],["Apakah sertifikasi DV360 otomatis memberi akses live seat?","Tidak. Learning credential dan akses akun/seat dikendalikan organisasi/partner dan ketentuan platform."]],
[["Line item","Unit konfigurasi delivery dalam DSP."],["Insertion order","Objek pengelompokan budget/flight dalam beberapa DSP."],["Seat","Akun/entitas buying access di platform/exchange."],["Change log","Catatan konfigurasi/perubahan dan alasan."]],"DPA-T06-CH05"),
G("Campaign setup/trafficking memastikan plan dapat diterjemahkan menjadi objek dan creative yang siap diperdagangkan. Brief, naming, IO/line item, deal IDs, audience, creative spec, click URL, trackers, macros, event tags, and approvals harus sinkron. Trafficking berbeda dari media strategy: tugasnya menjaga akurasi konfigurasi dan bukti QA, bukan menentukan seluruh business strategy.",
"SIMULATED — deal ID aktif tetapi creative tidak memenuhi format/SSL dan click macro salah. Campaign terlihat configured tetapi tidak eligible atau salah mengarahkan traffic. Pre-launch QA harus menguji actual rendering dan click path.",
["<b>Terima final brief.</b> Cocokkan plan, targeting, format, dates, budget, KPI, owner, and approval.","<b>Bangun trafficking map.</b> Hubungkan campaign/line item/deal/creative/tracker/landing page secara konsisten.","<b>Validasi spec dan macros.</b> Periksa dimensions, VAST/HTML5, SSL, click/impression trackers, URL encoding, and fallbacks.","<b>Jalankan end-to-end QA.</b> Simulasikan ad request, landing page, event firing, and platform acceptance."],
"Buat trafficking sheet, creative spec matrix, macro/URL map, tag map, deal checklist, and QA evidence for one synthetic DSP campaign.",
[["Apa risiko click macro salah?","Click-through dapat hilang, salah redirect, mengganggu billing atau memutus measurement."],["Mengapa trafficking sheet menjadi single source of truth?","Sheet mengikat object, tag, date, budget, creative, owner, approval, dan status untuk mencegah konfigurasi berbeda."],["Apa bukti QA selain upload success?","Preview/render evidence, click test, landing validation, tracking test, policy/approval, and sign-off."]],
[["Trafficking","Konfigurasi teknis campaign/creative/tag untuk delivery."],["VAST","Standar komunikasi untuk video ad serving/tracking."],["Macro","Token dinamis untuk menambahkan nilai tracking saat delivery/click."],["Fallback","Asset/behavior pengganti saat format utama tidak didukung."]],"DPA-T06-CH06"),
G("Bidding, budget, pacing, and frequency management mengontrol delivery dalam batas economics dan campaign objective. Pahami bid strategy, auction pressure, bid shading where relevant, win rate, clearing price, pacing algorithm, frequency caps, reach, and spend curve. Jangan mengubah bid/budget tanpa memeriksa inventory, audience, floor, conversion signals, and campaign stage. Platform automation berbeda sehingga jangan menganggap satu setting berlaku sama di seluruh DSP.",
"SIMULATED — campaign spend hanya 40% dari budget setelah 3 hari. Peningkatan bid mungkin membantu bila lost auctions karena price, tetapi tidak bila deal not eligible, creative rejected, audience terlalu sempit, atau supply timeout.",
["<b>Establish pacing baseline.</b> Bandingkan budget, elapsed flight, planned spend curve, actual spend, impressions, and outcome.","<b>Diagnose delivery.</b> Pisahkan price, inventory, audience, creative, deal, bid request, tracking, and approval issues.","<b>Optimize frequency.</b> Nilai unique reach, average frequency, segment saturation, and cross-device duplication.","<b>Control changes.</b> Catat bid/budget changes, rationale, observation window, guardrails, and rollback criteria."],
"Buat pacing simulator harian dengan planned vs actual spend, bid, win rate, CPM, frequency, reach, and outcomes. Simulasikan underdelivery, overspend, and fatigue; dokumentasikan root-cause decisions.",
[["Mengapa menaikkan bid tidak selalu menyelesaikan underspend?","Inventory eligibility, targeting, deal/creative issues, supply, and timeouts dapat menjadi bottleneck selain bid."],["Apa risiko frequency terlalu tinggi?","Waste, fatigue, negative experience, and diminishing incremental reach."],["Apa beda average CPM dan clearing price?","Average CPM merangkum biaya hasil delivery; clearing price adalah harga auction pada impression tertentu/menurut mekanisme platform."]],
[["Pacing","Kecepatan pembelanjaan budget sepanjang flight."],["Win rate","Proporsi bid opportunities yang dimenangkan."],["Frequency cap","Batas exposure per user/device dalam periode."],["Bid shading","Penyesuaian bid pada auction tertentu untuk menghindari overpay; metode platform berbeda."]],"DPA-T06-CH07"),
G("PMP, Preferred Deals, dan Programmatic Guaranteed mengubah cara advertiser mengakses publisher inventory dan menyepakati harga/delivery. Setiap deal memiliki buyer/seller IDs, deal ID, floor/fixed price, targeting, dates, format, priority, inventory scope, and delivery terms. Trader wajib menguji compatibility dan memahami apakah deal bersifat invitation, non-guaranteed, atau guaranteed; label platform dapat berbeda.",
"SIMULATED — publisher menawarkan PMP dengan floor CPM Rp45.000 dan forecast 2 juta impressions. Campaign mengaktifkan deal ID, tetapi buyer menggunakan seat yang salah. Tidak ada delivery meski bid kompetitif; deal ID/seat mapping harus di-verify.",
["<b>Bandingkan deal type.</b> Pelajari access, auction, price, inventory commitment, priority, and delivery guarantee.","<b>Negosiasikan scope.</b> Tetapkan format, audience, geo, floor/price, dates, volume, reporting, and cancellation/makegood terms.","<b>QA deal activation.</b> Verifikasi buyer seat, seller, deal ID, line item, targeting, creative, and inventory eligibility.","<b>Monitor deal delivery.</b> Pantau bid requests, matches, wins, spend, quality, and underdelivery."],
"Buat deal negotiation matrix dan activation checklist untuk PMP, Preferred, dan PG. Isikan seller/buyer seat, deal ID, floor/price, volume, formats, dates, targeting, guarantee, QA, and delivery escalation.",
[["Apa beda preferred deal dan PMP auction?","Preferred biasanya memberi akses/first look dengan harga tertentu tanpa guarantee; PMP umumnya private auction dengan buyers invited, terms platform-specific."],["Apa yang perlu dikonfirmasi sebelum PG?","Volume, dates, price, inventory, priority, format, audience, guarantee, makegood, cancellation, and measurement terms."],["Mengapa deal ID perlu di-test?","Deal dapat gagal karena seat/seller mismatch, targeting, format, dates, price, atau line-item setup."]],
[["Deal ID","Identifier untuk akses transaksi/inventory deal tertentu."],["Floor price","Batas harga minimum pada deal/inventory."],["Preferred deal","Akses first look/price agreed tanpa komitmen volume yang sama dengan PG."],["PG","Programmatic Guaranteed; transaksi dengan commitment delivery."]],"DPA-T06-CH08"),
G("Brand safety, suitability, viewability, invalid traffic, and supply quality adalah dimensi berbeda. Brand safety menghindari konten berisiko; suitability mencocokkan toleransi brand; viewability mengukur apakah iklan memenuhi kriteria terlihat; IVT mengidentifikasi traffic tidak valid; supply quality menilai transparency, duplication, fees, and publisher quality. Vendor verification memiliki methodology/coverage yang harus dipahami.",
"SIMULATED — report menunjukkan 70% viewable impressions, tetapi 8% IVT dan beberapa placement melanggar suitability. Viewability tinggi tidak membuat campaign aman atau efektif; metrics harus dibaca bersama dan coverage dilaporkan.",
["<b>Definisikan metrics.</b> Catat viewability standard, eligible/measured impressions, IVT definitions, brand-safety taxonomy, and exclusions.","<b>Set controls.</b> Gunakan inclusion/exclusion lists, category/content controls, seller transparency, and verification partners.","<b>Audit supply quality.</b> Periksa domain/app, ads.txt/sellers.json, reseller paths, fees, duplication, and reporting gaps.","<b>Interpret coverage.</b> Pisahkan unmeasured from failed, disclose vendor coverage, and escalate anomalies."],
"Buat supply-quality scorecard untuk 10 inventory sources: brand safety, suitability, viewability, IVT, seller authorization, fees, transparency, data coverage, and remediation.",
[["Apa beda viewability dengan attention?","Viewability mengukur peluang terlihat menurut standard; attention mengukur engagement/notice lebih jauh dan memerlukan metode berbeda."],["Mengapa unmeasured impression bukan otomatis failure?","Sebagian inventory tidak terukur karena coverage/technical limits; laporkan sebagai unmeasured terpisah dari non-viewable."],["Apakah ads.txt menjamin inventory aman?","Tidak. Ia membantu mengidentifikasi authorized sellers, tetapi fraud/suitability/viewability tetap membutuhkan controls lain."]],
[["IVT","Invalid Traffic, aktivitas trafik yang tidak valid."],["Viewability","Kelayakan impression terlihat menurut measurement standard."],["Brand suitability","Kesesuaian context terhadap toleransi dan nilai brand."],["Supply path optimization","Evaluasi jalur supply agar transparansi, quality, dan fees lebih baik."]],"DPA-T06-CH09"),
G("CM360 dan Floodlight memiliki peran ad-serving dan measurement yang perlu dibedakan dari DSP reporting. CM360 mengelola advertiser/campaign/site/placement/ad/creative/trackers; Floodlight mengukur activities/conversions menurut counting method, attribution, and window. Discrepancy antara DSP, CM360, dan analytics sering muncul dari event definition, time zone, click/view windows, deduplication, redirects, latency, and consent.",
"SIMULATED — DSP mencatat 900 conversions, CM360 760 Floodlight activities, GA4 620 purchases. Angka tidak dapat dibandingkan sebelum unit event, window, dedupe, timezone, consent, and transaction IDs disejajarkan.",
["<b>Map tracking roles.</b> Bedakan impression/click trackers, ad server, Floodlight activity, GA4 events, pixel/CAPI, and UTM.","<b>Define conversion.</b> Tentukan activity type, counting method, value, window, deduplication, and source of truth.","<b>QA integration.</b> Test tags, redirects, macros, event IDs, consent states, and platform logs.","<b>Reconcile discrepancy.</b> Align timezone/cutoff/window, compare eligible events, and document residual difference."],
"Buat measurement architecture diagram dan discrepancy reconciliation workbook yang membandingkan DSP, CM360/Floodlight, dan GA4. Include event mapping, window, timezone, dedupe, consent, and limits.",
[["Apa beda ad server dengan DSP?","Ad server mengelola ad decisioning/delivery/tracking; DSP mengelola buying/auction/targeting di inventory."],["Mengapa Floodlight counts dapat berbeda dengan GA4 purchase?","Counting method, attribution, time zone, identity, consent, deduplication, event definition, and processing berbeda."],["Mengapa UTM bukan pengganti Floodlight?","UTM memberi label campaign pada session/source; Floodlight merekam conversion activity sesuai setup measurement."]],
[["Floodlight","Sistem activity/conversion tracking dalam Campaign Manager 360."],["Counting method","Aturan apakah activity dihitung sekali, per session, atau setiap kejadian."],["Attribution window","Periode ketika interaksi dapat menerima credit conversion."],["Discrepancy","Perbedaan angka antara sistem yang perlu direkonsiliasi."]],"DPA-T06-CH10"),
G("Optimization dan post-campaign review mengevaluasi bukan hanya ROAS, tetapi delivery, supply quality, reach, frequency, margin, partner fees, audience, format, and incrementality limits. Report harus menjelaskan apa yang terjadi, mengapa diduga terjadi, bukti pendukung, alternatif penjelasan, dan tindakan berikutnya. Programmatic trader menjaga traceability perubahan agar learning dapat direplikasi.",
"SIMULATED — open auction memberikan CPM rendah tetapi IVT tinggi dan conversion quality rendah; PMP lebih mahal tetapi engagement dan incrementality test lebih baik. Keputusan mengubah mix harus membandingkan net cost dan kualitas outcome.",
["<b>Read performance by dimension.</b> Slice by DSP, deal, publisher, placement, format, audience, device, geo, and creative.","<b>Separate delivery and outcome.</b> Reconcile spend/impressions with viewability, IVT, reach, conversions, and contribution.","<b>Generate hypotheses.</b> Distinguish evidence, interpretation, confidence, and alternative cause.","<b>Recommend optimizations.</b> Set action, expected mechanism, budget impact, guardrail, owner, and review date."],
"Buat post-campaign report dan supply evaluation: delivery, spend, CPM, reach/frequency, viewability, IVT, deal quality, discrepancy, outcome, optimization changes, and next test agenda. Labeli data SYNTHETIC.",
[["Mengapa CPM tidak boleh menjadi satu-satunya optimization target?","Ia mengabaikan inventory quality, fraud, reach, outcomes, fees, and contribution."],["Apa hubungan optimization log dengan repeatability?","Log mencatat perubahan, alasan, dan hasil sehingga learning bisa direplikasi dan tim tidak mengulang kesalahan."],["Apa batas ROAS platform dalam menilai programmatic?","Attribution platform tidak otomatis mengukur causal impact, overlap, fee, margin, atau long-term value."]],
[["Post-campaign analysis","Evaluasi delivery, quality, outcomes, discrepancy, dan next action."],["Supply quality","Kualitas inventory/jalur dari sisi transparency, suitability, IVT, dan value."],["Optimization log","Catatan perubahan dan outcome untuk learning."],["Incrementality","Dampak tambahan di luar baseline/counterfactual."]],"DPA-T06-CH11"),
G("Capstone Programmatic menguji pemahaman supply chain hingga measurement, bukan hanya navigasi DSP. Paket kerja harus menghubungkan objective, audience, inventory/deal strategy, DSP setup, creative/trafficking, bidding/pacing, verification, CM360/Floodlight, discrepancy, dan reporting. Seluruh account/campaign/auction figures yang tidak berasal dari live account diberi label SIMULATED. Akses credential tidak berarti peserta memiliki live buying seat.",
"SIMULATED — brand e-commerce ingin reach dan qualified purchase di Indonesia. Capstone menyusun mix open auction, PMP, dan retail data signals, tetapi menguji inventory quality, tracking, conversion quality, dan cost path sebelum merekomendasikan scale.",
["<b>Design strategy.</b> Tetapkan audience, objective, channel role, inventory, deal, and success metrics.","<b>Build and QA.</b> Rancang DSP hierarchy, line items, creatives, tags, tracking, and launch checks.","<b>Trade and monitor.</b> Simulasikan bid/pacing/frequency/quality issues dan change log.","<b>Measure and defend.</b> Rekonsiliasi data, jelaskan limitations, lalu rekomendasikan next investment."],
"Siapkan DSP campaign blueprint, supply-chain diagram, audience/data matrix, deal matrix, trafficking sheet, bidding/pacing simulator, verification scorecard, CM360/Floodlight measurement spec, discrepancy log, dan executive trading recommendation.",
[["Apa yang harus bisa dijelaskan dalam programmatic capstone?","Mengapa supply/channel/deal dipilih, bagaimana buying berjalan, bagaimana kualitas dijaga, dan bagaimana hasil diukur."],["Apa batas latihan dengan synthetic data?","Ia membuktikan workflow, logic, and analysis—not live campaign performance, spend, platform access, or client results."],["Bagaimana menilai programmatic inventory yang terlihat murah?","Cek net fees, authorized sellers, quality, viewability, IVT, audience, outcome, and incremental value."]],
[["Programmatic blueprint","Desain integrated buying, supply, audience, operation, and measurement."],["Deal matrix","Perbandingan commercial/technical terms antar deals."],["Trading decision","Keputusan bid, pacing, inventory, and optimization berdasarkan evidence."],["Evidence pack","Artefak yang membuktikan proses, hasil, sumber, dan batas klaim."]],"DPA-T06-CH12")
],
retail:[
G("Retail Media dan Commerce Media menggunakan retailer/commerce ecosystem, shopping intent, product/catalog data, onsite/offsite inventory, dan sales signals untuk memengaruhi pembelian. Retail media network dapat menjual inventory pada aset retailer atau aktivasi offsite yang memakai data/measurement retailer. Definisi, data access, placement, dan attribution berbeda per platform; trader perlu memisahkan retailer-owned inventory, third-party activation, dan marketplace ads.",
"SIMULATED — brand FMCG membeli sponsored product pada marketplace dan offsite audience activation melalui retailer network. Yang pertama tampil saat pencarian/halaman produk; yang kedua menjangkau audience di luar marketplace. Keduanya tidak boleh dilaporkan sebagai satu placement.",
["<b>Petakan ecosystem.</b> Identifikasi retailer, network, advertiser, platform, seller, agency, data, inventory, and reporting owner.","<b>Kelompokkan media.</b> Bedakan onsite, offsite, in-store, sponsored search/product, display, video, and retail data activation.","<b>Audit access dan measurement.</b> Periksa eligibility, seller account, product feed, reporting, conversion window, and sales source.","<b>Hubungkan ke shopper journey.</b> Petakan discovery, consideration, comparison, add-to-cart, purchase, repeat, and store visit."],
"Buat retail media ecosystem map untuk satu kategori Indonesia: Shopee, Tokopedia/TikTok Shop, Lazada, atau Blibli sesuai akses produk. Tandai onsite/offsite/in-store, buyer, seller, data owner, metrics, dan limitations.",
[["Apa beda marketplace ads dan retail media network?","Marketplace ads adalah penempatan iklan dalam marketplace; RMN dapat mencakup inventory/advertising dari retailer dan aktivasi offsite berbasis retailer signals."],["Mengapa onsite dan offsite harus dipisah?","Inventory, audience, data activation, fee, attribution, dan measurement berbeda."],["Mengapa produk dan seller eligibility perlu dicek?","Ads hanya berguna bila SKU, stok, listing, content, dan account memenuhi syarat platform."]],
[["Retail Media Network","Retailer-owned/managed advertising capability dan data/inventory ecosystem."],["Onsite media","Placement pada platform/site/app milik retailer."],["Offsite media","Aktivasi iklan di luar properti retailer menggunakan eligible audience/data."],["Shopper journey","Rangkaian perilaku audience dalam discovery hingga purchase/repeat."]],"DPA-T07-CH01"),
G("Shopper journey berbeda menurut kategori, urgency, price, availability, and retail context. Purchase intent signal dapat berasal dari search terms marketplace, category browsing, product views, add-to-cart, loyalty, repeat purchase, store location, atau review. Data tersebut harus dipahami menurut coverage dan consent; jangan menganggap click atau product view sebagai purchase intent kuat tanpa evidence.",
"SIMULATED — shopper melihat sponsored product tiga kali tetapi tidak membeli karena stok kota habis dan rating rendah. Audience retargeting saja tidak menyelesaikan friction; product readiness dan availability perlu diperbaiki.",
["<b>Map shopping task.</b> Definisikan category entry, comparison, product evaluation, purchase, fulfillment, and repeat.","<b>Audit signals.</b> Bedakan query/search, browse, product detail, cart, sale, loyalty, review, and availability.","<b>Segment shoppers.</b> Kelompokkan new-to-brand, category buyers, loyalists, lapsed, and high-intent audiences jika platform mendukung.","<b>Translate insight.</b> Pilih content, product listing, sponsored placement, offer, and next action."],
"Buat shopper journey untuk satu kategori dan peta intent signals ke stage. Sertakan listing/review/availability issues, media opportunities, metrics, and evidence gaps.",
[["Apakah product view selalu berarti high intent?","Tidak. Ia dapat menunjukkan curiosity atau accidental browse; perlu konteks query, depth, add-to-cart, repeat, dan category behavior."],["Mengapa review dan availability penting bagi retail ads?","Media dapat mendorong traffic, tetapi listing trust, stock, pricing, and delivery influence conversion."],["Apa batas penggunaan loyalty data?","Eligibility, consent, purpose limitation, access, aggregation, and platform terms harus dipatuhi."]],
[["Purchase intent signal","Sinyal perilaku yang dapat menunjukkan kesiapan membeli."],["New-to-brand","Pelanggan yang belum/baru pertama membeli brand menurut definisi retailer."],["Digital shelf","Kualitas keberadaan produk di retailer digital: content, rating, review, availability, and search position."],["Availability","Ketersediaan stok/layanan pada lokasi dan periode."]],"DPA-T07-CH02"),
G("Retail Media Network menawarkan model managed/self-service, sponsored product/search, display/video, audience activation, and measurement. Platform Indonesia memiliki nomenclature, eligibility, and reporting yang berubah; kurikulum harus mengajarkan cara membaca help center/current product availability, bukan menghafal satu nama fitur. Seller, brand, distributor, and agency account roles juga dapat berbeda.",
"SIMULATED — seller marketplace memiliki akses sponsored product, tetapi tidak memenuhi eligibility offsite audience activation. Planner harus merancang campaign sesuai account access yang tersedia dan tidak menjanjikan inventory yang tidak dapat dibeli.",
["<b>Map platform products.</b> Catat sponsored product/search, display, video, onsite placements, offsite, and audience solutions.","<b>Audit account eligibility.</b> Periksa seller/brand status, catalog/SKU, billing, geo, campaign type, and access roles.","<b>Compare buying model.</b> Bedakan self-service auction, managed campaign, reserved placement, and retailer program terms.","<b>Check current taxonomy.</b> Verifikasi nomenclature, migration notices, limits, and measurement from provider documentation."],
"Buat platform comparison untuk tiga RMN/marketplace aktif yang dapat diakses: ad types, seller/advertiser eligibility, placement, billing, targeting, reporting, conversion measurement, and documentation link. Cantumkan last-checked date.",
[["Mengapa nama product/feature harus diverifikasi ulang?","Retail platform sering mengganti nama campaign, default optimization, eligibility, dan reporting."],["Apa yang perlu diperiksa sebelum memilih self-service vs managed?","Budget threshold, service scope, control, inventory, reporting, fee, data access, and campaign complexity."],["Apakah satu platform mapping berlaku untuk semua seller?","Tidak. Access dan ad products dapat berbeda menurut seller/brand status, region, category, and program eligibility."]],
[["RMN","Retail Media Network."],["Sponsored product","Iklan produk pada search/browse/listing placement."],["Managed service","Campaign dioperasikan retailer/agency sesuai scope layanan."],["Eligibility","Syarat akun/produk/market agar dapat menggunakan ad feature."]],"DPA-T07-CH03"),
G("Onsite Retail Media memanfaatkan sponsored products, sponsored search, sponsored brands/store, dan rekomendasi pada properti retailer. Search placement menangkap query/shopper intent; product placement memerlukan listing content, image, price, rating, inventory, and availability. Bid dan budget harus dibaca bersama organic rank, competition, margin, product-level ROAS/ACoS, and category economics.",
"SIMULATED — sponsored product mendapatkan impression dan click, tetapi ACoS tinggi karena product page kehilangan rating dan harga kurang kompetitif. Bid reduction saja tidak memperbaiki conversion; listing quality perlu diperbaiki.",
["<b>Audit product readiness.</b> Periksa title, image, description, attributes, category, price, stock, shipping, rating, review, and buy box/listing status.","<b>Rancang sponsored placement.</b> Pilih SKU, keyword/search target, budget, bid, placement, and campaign objective.","<b>Monitor product-level results.</b> Segmentasikan by SKU, query, placement, sales, margin, ACoS/ROAS, and new-to-brand if available.","<b>Optimasi listing dan bid.</b> Bedakan media issue dengan product-page issue; document test and change."],
"Buat onsite retail campaign plan untuk lima SKU: product readiness audit, keyword/product target, campaign structure, bid/budget assumptions, negative/exclusion logic, sales metrics, and listing improvement backlog.",
[["Apa hubungan listing quality dengan sponsored ad performance?","Ad dapat menghasilkan traffic; listing, availability, price, review, and fulfillment menentukan apakah traffic berkonversi."],["Apa beda ROAS dan ACoS?","ROAS adalah sales/ad spend; ACoS adalah ad spend/ad-attributed sales, sehingga keduanya berbanding terbalik jika basis sama."],["Mengapa perlu SKU-level analysis?","Aggregate campaign metrics dapat menutupi SKU bermargin rendah, low stock, atau listing yang tidak converting."]],
[["Sponsored product","Placement berbayar untuk mempromosikan SKU."],["ACoS","Advertising cost of sales = ad spend / attributed sales."],["Product feed","Data produk terstruktur untuk platform/ads."],["Product readiness","Kesiapan listing, price, stock, content, and fulfillment sebelum promosi."]],"DPA-T07-CH04"),
G("Offsite Retail Media mengaktifkan retailer audience/data pada inventory di luar properti retailer, misalnya display/video/social melalui partners. Measurement dapat memakai sales matching/closed-loop reporting, tetapi access, coverage, attribution window, and fees harus dipahami. Offsite audience bukan berarti data pelanggan bebas dipindahkan ke platform lain; privacy, consent, aggregation, and clean-room rules tetap berlaku.",
"SIMULATED — brand menjalankan offsite campaign pada audience category buyers. Laporan menunjukkan sales lift, tetapi hanya sebagian transaksi dapat dimatch dan control group berbeda ukuran. Klaim incrementality harus memperhitungkan match coverage, selection bias, and methodology.",
["<b>Define offsite use case.</b> Prospecting, retargeting, category expansion, or loyalty activation.","<b>Audit audience activation.</b> Periksa provider data, eligibility, consent, clean-room/partner terms, match and reach.","<b>Set measurement rules.</b> Definisikan sales window, eligible transactions, control/treatment, coverage, fee, and deduplication.","<b>Reconcile outcomes.</b> Compare delivery, matched sales, platform attribution, and incremental evidence."],
"Buat offsite retail media plan: audience source, activation channel, data governance, placements, measurement approach, match coverage assumption, control design, cost, and limitations.",
[["Apa beda offsite sales attribution dan incrementality?","Attribution memberi credit pada exposure menurut model/window; incrementality mengestimasi tambahan penjualan dibanding control/counterfactual."],["Mengapa match coverage harus dilaporkan?","Hanya transaksi/audience eligible yang dapat diukur; coverage rendah membatasi representativeness."],["Apa risiko mengaktifkan retailer data ke luar platform?","Privacy, consent, purpose limitation, partner terms, identity resolution, and security controls."]],
[["Offsite retail media","Aktivasi iklan di luar retailer property berbasis audience/data retailer."],["Closed-loop measurement","Penghubungan exposure media dengan transaksi/sales retailer."],["Match rate","Proporsi records yang dapat dicocokkan antara data sources."],["Clean room","Environment terkontrol untuk analisis dataset tanpa berbagi raw data secara bebas."]],"DPA-T07-CH05"),
G("Retail audience and first-party data digunakan untuk membuat segment seperti category buyers, loyalty members, lapsed purchasers, new-to-brand, high-value, and product affinities. Targeting bergantung pada taxonomy retailer, match coverage, scale, privacy, and platform controls. Audience strategy harus seimbang antara precision dan reach; segment terlalu kecil dapat menaikkan CPM, membatasi delivery, atau membuat hasil tidak stabil.","SIMULATED — segment loyalty top spenders hanya 15 ribu users dan CPM tinggi. Broad category buyers mencapai 1,2 juta; strategi dapat memakai broad prospecting lalu retargeting loyalists dengan offer yang berbeda.",["<b>Define segment logic.</b> Tulis transaction window, category/product, recency/frequency/value, loyalty, and exclusions.","<b>Audit scale and match.</b> Periksa eligible users, match rate, refresh cadence, overlap, and suppression.","<b>Align activation.</b> Pilih placement, message, offer, and bid sesuai segment intent/value.","<b>Govern data.</b> Document consent, retention, purpose, access, and platform limitations."],"Buat retail audience taxonomy untuk prospecting, new-to-brand, repeat, lapsed, and high-value segments. Sertakan logic, window, scale/match caveat, activation, suppression, and measurement.",[["Mengapa segment terlalu sempit berisiko?","Scale kecil dapat meningkatkan biaya, underdelivery, unstable measurement, dan overfrequency."],["Apa risiko menganggap retailer segment sama dengan CRM segment?","Definisi, refresh, identity, transaction coverage, and eligibility dapat berbeda."],["Mengapa suppression penting?","Mencegah budget/communication terbuang untuk customer yang sudah convert atau tidak eligible."]],[["Recency","Kedekatan waktu sejak transaksi/interaksi."],["Frequency","Jumlah transaksi/interaksi selama window."],["Monetary value","Nilai pembelian dalam periode."],["Audience overlap","Customer yang muncul pada beberapa segment."]],"DPA-T07-CH06"),
G("Product feed adalah representasi data produk yang dikirim ke marketplace, retailer, shopping engine, dan ad platform agar SKU dapat ditemukan, ditampilkan, divalidasi, serta dipromosikan. Digital shelf adalah pengalaman produk yang dilihat shopper pada retailer digital: judul, atribut, gambar, deskripsi, harga, stok, variasi, rating/review, ketersediaan, dan discoverability. Feed bukan satu format universal. Required attributes, naming, identifiers, image rules, category taxonomy, locale, currency, dan update mechanism berbeda menurut platform, kategori, pasar, dan tipe akun. Praktisi harus memetakan source of truth dari PIM/ERP/catalogue ke schema tujuan, menjaga konsistensi dengan landing page/checkout, dan memantau error, disapproval, stale data, serta perubahan taxonomy.","SIMULATED — katalog FMCG berisi 100 SKU. Sebagian item kehilangan GTIN, variasi ukuran memakai item_group_id yang tidak konsisten, harga feed berbeda dari landing page, dan image URL tidak dapat di-crawl. Hasilnya sebagian item ditolak atau eligibility-nya dibatasi. Tim tidak boleh sekadar mengulang upload; mereka harus mengidentifikasi sumber data, field mapping, aturan category, dan pemilik koreksi.",["<b>Map product data ownership.</b> Identifikasi PIM/ERP, seller centre, website, inventory/pricing source, product owner, SKU/SPU/variant identifiers, dan siapa yang menyetujui perubahan.","<b>Build platform/category schema.</b> Ambil required dan optional attributes dari dokumentasi/feed specification terkini per platform, kategori, market, dan account. Buat data dictionary serta mapping table; jangan menganggap field wajib sama di Google, TikTok, Lazada, atau marketplace lain.","<b>Validate feed and digital shelf.</b> QA title, description, category, brand, GTIN/identifier, variant/group ID, image URL/quality, landing page, price, currency, availability, stock, and policy/content consistency. Bandingkan feed dengan PDP dan checkout.","<b>Operate diagnostics and refresh.</b> Monitor processing errors, disapproval, warnings, missing attributes, stale price/stock, broken URLs, image failures, and update latency. Buat issue backlog, owner, severity, correction, resubmission, dan monitoring cadence."],"Buat product-feed audit workbook untuk minimal 20 SKU dari dua kategori. Sertakan source-of-truth map, platform/category attribute dictionary, field mapping untuk Google Merchant Center dan satu catalog/marketplace yang benar-benar dapat diakses, sample feed rows, validation rules, digital-shelf checklist, diagnostics/error log, owner, priority, dan refresh SLA. Tandai platform features yang tidak tersedia di Indonesia atau memerlukan managed-account eligibility sebagai conditional, bukan assumed access.",[["Apa sebab field wajib pada product feed tidak boleh dianggap sama untuk semua platform dan kategori?","Setiap platform dan kategori dapat memiliki taxonomy, mandatory attributes, allowed values, identifier rules, dan eligibility berbeda. Gunakan schema/dokumentasi tujuan yang sedang berlaku."],["Bagaimana menangani harga atau availability yang berbeda antara feed dan halaman produk?","Temukan source of truth, rekonsiliasi currency/time/update cadence, perbaiki sistem asal dan destination, lalu validasi ulang hingga feed, landing page, dan checkout konsisten. Jangan mengirim data yang diketahui salah."],["Apa perbedaan product feed dengan digital shelf?","Feed adalah struktur data produk yang disuplai ke platform; digital shelf adalah kondisi dan pengalaman produk yang dilihat shopper, termasuk konten, harga, stok, review, ranking, dan discoverability. Feed yang valid belum menjamin digital shelf berkualitas."]],[["Product feed","Data produk terstruktur yang dikirim ke platform untuk katalog, listing, dan/atau iklan."],["Attribute mapping","Pemetaan field sumber ke atribut dan format yang diwajibkan platform tujuan."],["GTIN","Global Trade Item Number; identifier produk global jika berlaku dan tersedia."],["Digital shelf","Kualitas tampilan dan discoverability produk pada retailer/marketplace digital."]],"DPA-T07-CH07"),
G("Retail activation dan optimization menggabungkan campaign configuration, product/feed readiness, bid/budget, placement, query, product availability, pricing, promotion, reviews, and sales signals. Optimasi dilakukan pada level retailer, campaign, keyword, placement, and SKU. Perubahan bid harus dibandingkan dengan stock/price/promo agar kenaikan sales tidak salah diatribusikan ke media. Aktivasi juga dapat mencakup in-store retail media seperti screen, audio, shelf signage, kiosk, sampling, QR, dan proximity placements. Perencanaan in-store memerlukan store list, inventory/location map, footfall/dwell methodology, operating hours, installation, uptime, creative specification, proof-of-play, store operations, safety, serta pengukuran yang tidak menyamakan plays atau footfall dengan unique ad exposure.","SIMULATED — ROAS turun setelah seller menaikkan price dan stock-out pada dua SKU terlaris. Mengurangi bid pada seluruh account justru dapat merugikan SKU yang tetap tersedia. Segmentasikan dan koordinasikan media dengan merchandising/ops. SIMULATED — sebagian budget juga dialokasikan ke layar in-store pada 20 toko. Beberapa screen offline dan footfall memakai periode berbeda; tim harus mengecek proof-of-play, uptime, store list, dan sales/control period sebelum menyatakan exposure atau lift.",["<b>Setup activation.</b> Validasi seller/account, SKU/catalog, target, placement, budget, bid, dates, and creative.","<b>Monitor retail levers.</b> Check spend, impressions, clicks, CPC, orders, sales, ACoS/ROAS, stock, price, promo, and rating.","<b>Diagnose product vs media.</b> Pisahkan ad delivery, search rank, product page, price/availability, and competitor action.","<b>Run controlled changes.</b> Catat SKU/target/bid change, observation window, guardrail, and retail-team dependency.","<b>Execute in-store controls.</b> Validasi store selection, placement/inventory map, daypart, creative specs, installation, uptime, proof-of-play, store staff/operations, safety, dan measurement caveats."],"Buat retail optimization log dari data SIMULATED 14 hari: per SKU/query, bid, spend, clicks, sales, stock, price, promo, rating, ACoS, root cause, action, and result. Tambahkan modul in-store: placement map untuk 20 toko, flight/daypart, creative spec, store operations checklist, proof-of-play evidence, uptime exception log, dan sales/footfall measurement caveats.",[["Mengapa ROAS bisa turun meski campaign setting tidak berubah?","Harga, stock, competitor price, ratings, product content, seasonality, and auction competition dapat berubah."],["Apa yang harus dilakukan bila stock-out?","Pause/exclude affected SKU atau ubah destination/offer; koordinasikan inventory dan jangan biarkan spend mendorong item unavailable."],["Mengapa perubahan bid perlu change log?","Agar dampak bisa ditelusuri dan tidak tercampur dengan price/promo/stock changes."],["Apa itu proof-of-play?","Bukti bahwa aset ditayangkan pada screen/placement sesuai waktu/ketentuan yang dibooking."],["Mengapa footfall tidak sama dengan ad exposure?","Footfall mengukur kunjungan lokasi; tidak membuktikan setiap orang melihat placement atau mengingat pesan."],["Apa kontrol operasional khas in-store?","Store availability, uptime, installation, staff, display condition, operating hours, and safety."]],[["ACoS","Ad spend dibagi attributed sales."],["ROAS","Attributed sales/revenue dibagi ad spend."],["Stock-out","Kondisi produk tidak tersedia untuk dijual."],["Retail readiness","Kesiapan produk/listing/stock/price untuk menerima traffic."],["In-store media","Media pada lokasi fisik retailer/store."],["Proof-of-play","Log/foto/bukti penayangan layar/placement."],["Footfall","Jumlah pengunjung yang memasuki area/store menurut sensor/metode."],["Daypart","Segment waktu dalam hari untuk penjadwalan media."]],"DPA-T07-CH08"),
G("Retail measurement menggabungkan platform ad reports, retailer sales, SKU economics, new-to-brand, marketplace share, product margin, and incrementality. Attribution window, category, campaign eligibility, returns/cancellations, VAT/fees, and sales definitions perlu disamakan. ROAS/ACoS tidak menunjukkan profit bila margin/discount/fulfillment belum dihitung. Lift tests dan holdout dapat digunakan bila retailer methodology dan sample mendukung.",
"SIMULATED — campaign memiliki ROAS 5x, tetapi margin kontribusi produk hanya 12% dan promo besar. Setelah fees/returns, campaign bisa negatif. Measurement harus menghubungkan ad cost dengan product contribution, bukan sales gross saja.",
["<b>Define sales basis.</b> Bedakan gross/net, attributed sales, returns, cancelled orders, brand vs category, new-to-brand, and margin.","<b>Reconcile data.</b> Align date, SKU, currency, tax, attribution window, campaign, and reporting latency.","<b>Assess incrementality.</b> Design holdout/geo test if eligible; document limitations and sample.","<b>Translate into decision.</b> Evaluate incremental contribution, inventory, price, channel, and next budget."],
"Buat retail effectiveness dashboard spec dan analysis memo: spend, attributed sales, ACoS/ROAS, margin, returns, new-to-brand, stock, match coverage, and incrementality test design.",
[["Mengapa ROAS tinggi belum tentu profitable?","Gross sales tidak memperhitungkan margin, discount, returns, fulfillment, retailer fees, dan incremental contribution."],["Apa yang perlu disamakan saat reconciliation?","Date, SKU, currency/tax, sales basis, attribution window, cancellations/returns, campaign tags, and data latency."],["Apa batas closed-loop reporting?","Coverage, match rate, attribution methodology, and selection bias membatasi causal interpretation."]],
[["New-to-brand","Pembeli yang belum membeli brand dalam periode definisi retailer."],["Contribution margin","Revenue dikurangi biaya variabel/komersial yang relevan."],["Return rate","Porsi order/sales yang dikembalikan."],["Incrementality test","Desain untuk mengestimasi tambahan outcome akibat media."]],"DPA-T07-CH09"),
G("Capstone Retail & Commerce Media menyatukan shopper insight, retailer ecosystem, product readiness, onsite/offsite/in-store media, audience, activation, measurement, and profitability. Output bukan sekadar media plan marketplace; ia harus menjelaskan SKU priority, data/access, placement, forecast, operations, stock dependencies, closed-loop metrics, and test design. Cantumkan ketersediaan produk dan access assumptions berdasarkan provider yang diverifikasi.",
"SIMULATED — sebuah brand makanan mengalokasikan budget ke marketplace sponsored products, retail audience offsite, dan in-store screens di kota prioritas. Capstone memperhitungkan listing, stock, delivery service, margin, and matched-sales limits.",
["<b>Frame category problem.</b> Tentukan shopper, product, retailer, commercial objective, stock, price, and distribution.","<b>Design media architecture.</b> Pilih onsite/offsite/in-store, audience, SKU, budget, flight, and channel roles.","<b>Specify activation/governance.</b> Siapkan feed/listing, bidding, store ops, access, creative, tracking, and QA.","<b>Measure economics.</b> Reconcile ad sales, margin, returns, stock, and incrementality; define next decision."],
"Siapkan retail media strategy 90 hari plus workbook: retailer comparison, shopper journey, SKU readiness, inventory/placement matrix, audience segments, budget scenarios, campaign setup, measurement, sales/margin dashboard, and recommendation.",
[["Apa yang membedakan retail capstone dari paid search/social?","Retail harus mengintegrasikan marketplace/retailer product data, stock, listing, shopper behavior, sales reconciliation, and margin."],["Bagaimana memastikan platform recommendations current?","Cek official help center, local advertiser eligibility, product taxonomy, update date, and current account access."],["Apa keputusan utama yang harus dipresentasikan?","Retailer/channel/SKU investment, budget, stock/readiness actions, risk, measurement confidence, and next scale/hold decision."]],
[["Retail media strategy","Rencana penggunaan inventory/data retailer untuk memengaruhi shopping outcomes."],["SKU","Stock Keeping Unit; unit identifikasi produk."],["Closed-loop sales","Sales yang dihubungkan dengan media exposure menurut provider methodology."],["Retail capstone","Paket bukti strategy-to-sales untuk retailer/commerce media."]],"DPA-T07-CH10")
],
investment:[
G("Media Investment dan Publisher Partnerships berfokus pada pembelian inventory secara komersial dan pengelolaan relasi media owner. Fungsi ini berbeda dari media planning yang merancang channel mix dan forecast, serta berbeda dari biddable/programmatic yang membeli melalui auction/DSP. Investment specialist mengevaluasi rate, audience, package, value-add, supply, terms, contract, delivery, and value-for-money.",
"SIMULATED — publisher menawarkan premium homepage takeover, sponsorship, dan ROS display. Buyer perlu membedakan guaranteed exposure, share-of-voice, audience profile, added value, tracking, and cancellation terms sebelum menilai penawaran.",
["<b>Petakan ecosystem.</b> Identifikasi media owner, sales house, publisher rep, agency investment, trading desk, and Ad Ops.","<b>Kelompokkan buying route.</b> Bedakan direct IO, sponsorship, reserved inventory, network, deal, dan auction-based buying.","<b>Tentukan commercial criteria.</b> Audience, placement, rate, availability, reach, quality, bonus, and measurement.","<b>Document accountability.</b> Catat approval, owner, contract, cancellation, delivery, proof, and invoice."],
"Buat media owner landscape dan buying route map untuk satu kategori. Tulis siapa pemilik inventory, siapa bernegosiasi, siapa approve, siapa traffick, serta bukti delivery/billing yang dibutuhkan.",
[["Apa beda Media Investment dengan Programmatic Trading?","Investment menegosiasikan/membeli inventory/partnership secara komersial; Programmatic Trader mengelola buying berbasis DSP/auction/deal."],["Apa beda Media Planner dengan Media Buyer?","Planner menyusun strategy/mix/budget/forecast; buyer menegosiasikan rates, terms, booking, dan inventory delivery."],["Mengapa ownership map penting?","Agar negotiation, approval, booking, tracking, QA, and invoice memiliki accountable owner yang jelas."]],
[["Media owner","Pemilik/pengelola inventory dan paket media."],["Direct buy","Pembelian inventory langsung melalui publisher/media owner."],["Investment","Pengalokasian/pembelian media dan penilaian nilai komersialnya."],["Booking","Komitmen inventory/tanggal/volume sesuai terms."]],"DPA-T08-CH01"),
G("Inventory evaluation menilai audience fit, reach, context, format, quality, availability, exclusivity, placement, package flexibility, and pricing. Media kit menyediakan deskripsi inventory, tetapi klaim reach/circulation perlu diperiksa berdasarkan source, period, methodology, duplication, and target. Value bukan sekadar audience besar; premium context, relevance, attention, and commercial guarantee juga penting.",
"SIMULATED — dua media owner menawarkan reach 1 juta. Satu menggunakan monthly unique users, satu menggunakan total visits; angka tak comparable. Buyer harus meminta definition, data source, period, audience split, and delivery method.",
["<b>Collect media evidence.</b> Minta media kit, audience profile, traffic/reach, format, dates, availability, and measurement source.","<b>Normalize units.</b> Samakan unique users, impressions, page views, GRP, circulation, duration, geography, and time window.","<b>Assess value.</b> Nilai audience quality, context, attention, exclusivity, delivery guarantee, and cost.","<b>Record caveats.</b> Tandai unverified claims, methodology gaps, and negotiated terms."],
"Buat publisher inventory scorecard untuk lima opsi dengan audience, reach definition, format, quality, availability, rate, value-add, verification, methodology, dan recommended use.",
[["Mengapa media kit tidak boleh diterima tanpa verifikasi?","Reach, circulation, audience and engagement claims dapat memakai definisi/periode berbeda atau self-reported."],["Apa yang membuat proposal media value comparable?","Satuan, audience, dates, placements, format, reporting, measurement, exclusivity, fees, and contract basis harus dinormalisasi."],["Bagaimana menilai value-add?","Periksa placement, audience, timing, guarantee, production/measurement cost, and whether it substitutes paid inventory."]],
[["Media kit","Dokumen komersial yang merangkum audience, inventory, formats, and rates."],["Unique reach","Orang/household unik menurut metode dan periode tertentu."],["Value-add","Inventory/service tambahan di luar paid commitment utama."],["Share of voice","Proporsi exposure/voice dalam kategori menurut definisi metric."]],"DPA-T08-CH02"),
G("RFP/RFQ mengubah kebutuhan media menjadi permintaan proposal atau quotation yang dapat dibandingkan. Dokumen harus menetapkan objective, target, geography, dates, format, deliverables, KPI, audience requirement, budget range, measurement, brand safety, and commercial terms. Proposal review memeriksa completeness, assumptions, exclusions, rate basis, bonus, agency fee, production, data/measurement cost, and cancellation policy.",
"SIMULATED — satu publisher memberi gross rate, lainnya net rate setelah discount; proposal A menyertakan production fee sementara B tidak. Tanpa normalized cost sheet, perbandingan tidak apple-to-apple.",
["<b>Draft RFP.</b> Masukkan scope, KPI, audience, inventory, timeframe, deliverables, required data, and response format.","<b>Set evaluation criteria.</b> Tentukan must-have, weighted score, commercial, audience, quality, and execution risk.","<b>Normalize quote.</b> Pisahkan gross/net, discount, bonus, agency fee, production, tax, cancellation, and makegood.","<b>Record clarification.</b> Minta jawaban tertulis untuk exclusions, assumptions, and delivery commitments."],
"Buat RFP template dan proposal comparison untuk tiga publisher. Sertakan standardized fields, weighted scoring, commercial normalization, clarification log, and recommendation.",
[["Apa beda RFP dan RFQ?","RFP meminta solusi/proposal yang menjelaskan approach; RFQ meminta quotation untuk scope/requirements yang lebih terdefinisi."],["Mengapa gross dan net rate harus dipisah?","Discount/commission/fees dapat membuat quoted price tidak comparable dengan final payable amount."],["Apa risiko added value dijadikan pengganti discount?","Bonus mungkin tidak relevan, tidak guaranteed, atau memiliki kualitas/jangkauan berbeda dari paid inventory."]],
[["RFP","Request for Proposal untuk solusi dan penawaran."],["RFQ","Request for Quotation untuk harga atas scope tertentu."],["Gross rate","Rate sebelum discount/fee tertentu."],["Net rate","Rate setelah discount/commission sesuai definisi kontrak."]],"DPA-T08-CH03"),
G("Commercial benchmarking membandingkan cost dan value menggunakan unit yang disamakan. CPM, CPP, cost per unique reach, sponsorship rate, package pricing, discount, and added value harus memiliki target universe, dates, format, geography, and delivery definitions yang jelas. Historical rate bukan otomatis market benchmark terkini. Buyer perlu menyimpan source, date, volume tier, currency, and negotiation condition.",
"SIMULATED — rate publisher turun 15%, namun placement dipindah dari premium homepage ke remnant ROS. Harga lebih murah tetapi value berubah; benchmark harus memperhitungkan inventory tier dan guarantee.",
["<b>Normalize benchmark.</b> Samakan format, placement, date, target, unit, volume, currency, and billable basis.","<b>Segment pricing.</b> Pisahkan premium, ROS, sponsorship, fixed, CPM, CPC, CPP, and bundle.","<b>Assess total value.</b> Sertakan discount, added value, production, data, measurement, and operational fee.","<b>Set benchmark confidence.</b> Catat sample size, source, age, market, and negotiation context."],
"Buat benchmark workbook dengan lima publisher packages. Hitung net CPM/cost per reach, total cost, bonus value, unit comparability, benchmark confidence, and recommended negotiation anchor.",
[["Mengapa rate benchmark lama perlu caveat?","Inventory, market demand, inflation, seasonality, package, and commercial conditions berubah."],["Apa perbedaan cost efficiency dan value?","Cost efficiency menilai biaya per unit; value juga menilai quality, relevance, outcomes, guarantees, and audience context."],["Apa dampak package bundling?","Bundling bisa memberi efficiency tetapi menyamarkan rate per asset/placement dan mengurangi flexibility."]],
[["CPM","Cost per thousand impressions."],["CPP","Cost per rating point."],["Net media cost","Biaya media yang dibayar setelah terms/discount sesuai definisi."],["Benchmark confidence","Tingkat keyakinan benchmark berdasar sumber, recency, sample, and comparability."]],"DPA-T08-CH04"),
G("Negotiation media mengelola price, inventory, quality, dates, exclusivity, cancellation, makegood, payment, proof, data, and partnership value. Negotiation prep dimulai dari BATNA, objective, target/limit, leverage, alternative suppliers, and commercial priorities. Added value harus dinilai menurut audience dan delivery, bukan sekadar nominal rate-card yang tidak terpakai.",
"SIMULATED — publisher tidak dapat menurunkan rate, tetapi dapat memberi incremental home-page days, data report, and cancellation flexibility. Buyer menilai apakah konsesi tersebut benar-benar meningkatkan client value.",
["<b>Prepare negotiation.</b> Tentukan objective, walk-away, target, BATNA, volume, timing, and leverage.","<b>Prioritize terms.</b> Negosiasikan rate, audience, position, exclusivity, added value, cancellation, makegood, and reporting.","<b>Quantify concessions.</b> Hitung nilai/impact concession dan cek apakah deliverable benar-benar useful.","<b>Document agreement.</b> Catat final terms, validity, approver, responsibilities, and escalation."],
"Buat negotiation plan dan value tracker: target/limit, BATNA, concessions, added value, contract terms, risk, approval, and post-negotiation summary. Simulasikan vendor negotiation.",
[["Apa fungsi BATNA?","Alternatif terbaik jika kesepakatan tidak tercapai; memberi batas rasional dan mengurangi keputusan emosional."],["Mengapa semua added value tidak setara?","Nilainya tergantung audience, placement, timing, guarantee, production cost, and measurement."],["Apa yang harus didokumentasikan setelah negotiation?","Final rate, discount, scope, dates, inventory, cancellation, makegood, payment, proof, and authorized approver."]],
[["BATNA","Best Alternative to a Negotiated Agreement."],["Makegood","Kompensasi/penayangan pengganti sesuai shortfall terms."],["Exclusivity","Hak/ketentuan eksklusif pada kategori/slot/period."],["Concession","Kompromi atau nilai yang diberikan dalam negotiation."]],"DPA-T08-CH05"),
G("Insertion Order dan kontrak mengikat scope media buying menjadi komitmen komersial. IO perlu advertiser, publisher, placement, format, dates, quantity, rate, cost, currency, tax, cancellation, creative deadline, tracking, reporting, payment, and sign-off. Legal terms dapat meliputi indemnity, privacy, IP, liability, exclusivity, makegood, force majeure, and termination; buyer bukan pengganti legal counsel tetapi harus mengenali escalation points.",
"SIMULATED — IO mencantumkan 5 juta impressions, tetapi email negosiasi menyatakan 3 juta guaranteed dan 2 juta bonus. Jika tidak ditulis, invoice dan makegood dapat diperdebatkan. Scope final harus sama di IO, booking confirmation, and trafficking.",
["<b>Draft IO.</b> Isi legal entities, campaign, inventory, format, dates, volume, rates, fees, and currency.","<b>Check delivery terms.</b> Bedakan guaranteed, estimated, bonus, value-add, and billable impressions.","<b>Review clauses.</b> Periksa cancellation, makegood, creative deadlines, tracking, reporting, payment, privacy, and rights.","<b>Secure approval.</b> Cocokkan budget approval, signatures, version, and booking confirmation."],
"Buat IO checklist dan sample order form untuk campaign latihan. Bandingkan negotiated terms dengan signed IO dan trafficking sheet; tandai discrepancy/approval exceptions.",
[["Apa risiko bonus tidak tercatat terpisah?","Volume billable dan bonus dapat tertukar sehingga delivery/invoice reconciliation tidak akurat."],["Siapa yang menyetujui legal clause?","Procurement/legal/authorized approver sesuai governance organisasi; media buyer menandai dan mengeskalasi risiko."],["Mengapa IO harus selaras dengan trafficking sheet?","Agar inventory, dates, formats, volume, rates, tags, and responsibilities sama di dokumen komersial dan operasional."]],
[["Insertion Order","Dokumen booking/komitmen media."],["Billable delivery","Delivery yang menjadi dasar penagihan."],["Cancellation clause","Ketentuan pembatalan dan biaya/notice."],["Makegood clause","Ketentuan pemulihan jika delivery tidak sesuai commitment."]],"DPA-T08-CH06"),
G("Delivery stewardship memastikan media owner memenuhi booking dan terms. Buyer memonitor booked vs delivered, dates, placements, creative, proof-of-posting/proof-of-play, audience, quality, and shortfall. Makegood bukan permintaan informal; ia mengikuti contract, tolerance, deadline, and evidence. Monitor campaign secara berkala agar masalah bisa diperbaiki sebelum end-of-flight.",
"SIMULATED — publisher menjanjikan 100 spot radio, tetapi proof menunjukkan 88 spot dan beberapa jadwal di luar agreed daypart. Buyer menyiapkan discrepancy evidence dan mengajukan makegood sesuai IO.",
["<b>Set delivery tracker.</b> Catat booking, placement, volume, schedule, rate, and evidence owner.","<b>Monitor proof.</b> Periksa proof-of-posting/play, screenshots, log, photos, affidavit, and schedule.","<b>Quantify shortfall.</b> Hitung gap dengan agreed tolerance dan billable basis.","<b>Claim remediation.</b> Ajukan makegood/refund/credit sesuai clause, deadline, and client approval."],
"Buat delivery tracker dan proof checklist untuk tiga publisher. Simulasikan underdelivery 12%; hitung shortfall, bukti yang diperlukan, makegood options, dan client communication.",
[["Apa beda proof-of-posting dan proof-of-play?","Proof-of-posting mendokumentasikan publication placement; proof-of-play membuktikan screen/audio/spot diputar sesuai log."],["Mengapa shortfall tidak boleh langsung diasumsikan berdasarkan impressions?","Contract mungkin memakai billable basis, tolerance, sampling, or alternative delivery definition."],["Kapan makegood harus dieskalasi?","Saat delivery di luar tolerance, bukti tidak lengkap, deadline terlewati, atau remedy tidak sesuai kontrak."]],
[["Proof of posting","Bukti placement/publikasi sesuai booking."],["Proof of play","Bukti spot/media diputar sesuai jadwal."],["Shortfall","Kekurangan delivery relatif pada commitment."],["Makegood","Kompensasi delivery sesuai perjanjian."]],"DPA-T08-CH07"),
G("Invoice reconciliation menghubungkan IO, vendor invoice, rate, volume, dates, placement, currency, tax, fees, discount, bonus, makegood, and proof. Buyer harus membedakan planned, contracted, delivered, and billable basis. Variance dapat berasal dari taxes, FX, cancellation, underdelivery, extra placement, or contract amendments. Semua adjustment harus memiliki evidence dan approver.",
"SIMULATED — IO Rp100 juta net, invoice Rp112 juta karena production fee dan tax ditambah. Jika production fee sudah termasuk di rate, invoice perlu clarification. Finance tidak boleh membayar berdasarkan summary tanpa line-item evidence.",
["<b>Match documents.</b> Cocokkan IO/contract, amendments, invoice, delivery report, and proof.","<b>Recalculate.</b> Cek unit × rate, discount, tax, currency, agency fee, production, bonus, and makegood.","<b>Investigate variance.</b> Kategorikan billing error, delivery gap, FX/tax, scope change, or legitimate add-on.","<b>Close with controls.</b> Dapatkan correction/credit note, approvals, audit trail, and archive."],
"Buat reconciliation workbook dari satu IO dan invoice sintetis. Gunakan line-item matching, formula checks, variance categories, evidence links, approval status, and payment recommendation.",
[["Apa beda invoice variance dan delivery variance?","Invoice variance adalah selisih amount/terms; delivery variance adalah perbedaan volume/placement/flight terhadap booking."],["Apa yang dilakukan bila currency/tax tidak cocok?","Verifikasi kontrak, exchange-rate basis, tax treatment, legal entity, and finance rules sebelum approve."],["Mengapa audit trail perlu disimpan?","Memudahkan dispute, finance approval, month-end close, compliance, and vendor accountability."]],
[["Reconciliation","Pencocokan dokumen dan angka antar sistem."],["Credit note","Dokumen koreksi pengurang invoice."],["Variance","Selisih antara nilai/volume yang diharapkan dan actual."],["Audit trail","Bukti perubahan, approval, dan keputusan yang dapat ditelusuri."]],"DPA-T08-CH08"),
G("Investment evaluation menilai hasil pembelian dan hubungan media owner setelah campaign. Analisis mencakup cost, delivery, audience quality, placement, value-add, fees, makegood, effectiveness, and future leverage. Negosiasi berikutnya menggunakan evidence, bukan sekadar meminta discount. Buyer harus menyampaikan value story kepada planner/finance/client serta memisahkan hasil komersial dari performance campaign.",
"SIMULATED — publisher memberi bonus 20% inventory tetapi audience overlap dengan media utama sangat tinggi. Nilai incremental reach rendah; renegotiation perlu fokus pada placement/context atau measurement, bukan bonus impressions lagi.",
["<b>Review commercial outcome.</b> Bandingkan contracted/net cost, delivery, bonus, fees, and makegood.","<b>Assess audience/value.</b> Periksa reach quality, duplication, context, premium placements, and outcome evidence.","<b>Build partner scorecard.</b> Nilai reliability, responsiveness, transparency, value, and compliance.","<b>Recommend next deal.</b> Tetapkan renewal, renegotiation, alternative partner, or escalation."],
"Buat media investment review satu kuartal: vendor scorecard, rate/value history, delivery, quality, audience overlap, discrepancy, recommendation, and negotiation agenda.",
[["Mengapa added value dapat bernilai rendah?","Jika audience overlap, timing, format, or quality tidak mendukung objective, bonus volume tidak menambah incremental value."],["Apa beda cost saving dan value creation?","Cost saving menurunkan spend; value creation meningkatkan kualitas, audience, outcome, reliability, or flexibility."],["Apa bukti partner layak dipertahankan?","Delivery reliability, commercial fairness, transparency, issue resolution, audience value, and measurable contribution."]],
[["Media value","Nilai gabungan dari audience, context, delivery, cost, and outcome."],["Vendor scorecard","Penilaian supplier berdasar performance, cost, service, quality, and governance."],["Rate history","Catatan harga/terms lintas campaign/periode."],["Renewal","Perpanjangan kerja sama atau booking dengan terms baru."]],"DPA-T08-CH09"),
G("Capstone Media Buying/Investment membuktikan kemampuan membeli dan menjaga nilai inventory secara komersial dari RFP sampai invoice. Paket harus mencakup media owner mapping, inventory evaluation, proposal normalization, negotiation, IO/contract, delivery stewardship, proof, reconciliation, and investment review. Track ini tidak mengajarkan DSP bidding sebagai kompetensi inti; direct publisher buying menjadi fokus, dengan auction/platform buying sebagai cross-track awareness.",
"SIMULATED — brand meminta sponsorship 6 minggu, display package, and live activation. Buyer harus memilih publisher, negotiate rates/terms, coordinate production/creative, monitor proof and billing, dan menilai apakah package layak diperpanjang.",
["<b>Source and evaluate.</b> Buat longlist media owner, inventory, audience, rates, and fit.","<b>Negotiate and contract.</b> Bangun RFP, comparison, negotiation plan, and signed IO.","<b>Steward delivery.</b> Track creative, timing, proof, shortfall, and remediation.","<b>Reconcile and review.</b> Close invoice, score partner, and recommend investment next cycle."],
"Siapkan complete buying pack: media owner map, RFP, proposal comparison, negotiation plan, signed-style IO sample, trafficking handoff, delivery/proof tracker, reconciliation workbook, and investment review deck.",
[["Apa yang membedakan buyer capstone dengan media plan?","Buyer capstone membuktikan commercial procurement, negotiation, contract, delivery, proof, and financial control."],["Apa hubungan buyer dengan Ad Ops?","Buyer/Investment mengatur deal/terms dan booking; Ad Ops menerjemahkan booking ke trafficking/tracking/QA; planner memastikan tujuan media."],["Bagaimana membuktikan negotiation berhasil?","Bandingkan baseline/alternative, final terms, total cost, inventory quality, delivery, added value actually used, and risks."]],
[["Publisher partnership","Hubungan komersial/operasional dengan media owner."],["RFP pack","Dokumen permintaan dan evaluasi proposal."],["IO pack","Dokumen komitmen pembelian dan terms."],["Investment review","Penilaian total value/efficiency atas pembelian media."]],"DPA-T08-CH10")
],
adops:[
G("Ad Operations menghubungkan media plan, platform/ad server, publisher, creative, tracking, verification, dan analytics. Tugas utamanya memastikan campaign dikonfigurasi, ditayangkan, dilacak, dan direkonsiliasi dengan benar—bukan menetapkan seluruh audience strategy atau budget allocation. Ekosistem dapat meliputi Google Ads, Meta, TikTok, LinkedIn, DV360, CM360, retailer platforms, dan direct publisher placements. Scope kerja mengikuti platform yang dipakai klien.",
"SIMULATED — campaign paid social, programmatic, dan publisher display menggunakan naming/UTM/tracking berbeda. Ad Ops membuat operation map agar creative, URL, pixels, CM360 tags, dates, approvals, and reporting definitions konsisten.",
["<b>Map ecosystem.</b> Identifikasi advertiser, ad platform, ad server, publisher, tracker, analytics, verification, and owner.","<b>Define operation boundary.</b> Pisahkan media strategy/buying dari trafficking, technical setup, QA, monitoring, and reconciliation.","<b>Set governance.</b> Tentukan naming, permission, approval, version control, change log, and evidence requirements.","<b>Plan handoff.</b> Pastikan brief, assets, dates, URLs, tracking, targeting, and budget final sebelum activation."],
"Buat cross-platform Ad Ops ecosystem diagram untuk satu campaign: platform roles, ad server, tags/pixels, publisher, verification, ownership, approvals, and evidence trail.",
[["Apa beda Ad Ops dan Media Buyer?","Ad Ops menjalankan technical trafficking, tracking, QA, and delivery control; buyer mengelola inventory purchase, rates, and commercial terms."],["Apa beda Ad Ops dan performance specialist?","Performance specialist mengelola audience/bidding/creative optimization; Ad Ops memastikan setup teknis dan measurement berfungsi."],["Mengapa multi-platform governance penting?","Tanpa naming, versioning, access, and approval yang konsisten, kesalahan sulit dilacak antar channel."]],
[["Ad Operations","Fungsi teknis untuk setup, trafficking, tracking, QA, delivery, and reconciliation."],["Trafficking","Penerjemahan brief/booking menjadi konfigurasi campaign/placement/ad/tag."],["Ad server","Sistem ad decisioning/delivery/tracking."],["Change log","Catatan perubahan konfigurasi beserta alasan dan approver."]],"DPA-T09-CH01"),
G("Campaign brief dan trafficking sheet adalah single source of truth operasional. Setiap object perlu advertiser/client, campaign, platform/publisher, placement/ad set/line item, creative, format, URL, click tracker, pixel/event, targeting, flight, budget, owner, approval, dan status. Naming taxonomy harus memudahkan identifikasi sekaligus kompatibel dengan reporting; jangan menaruh data pribadi di parameter atau URL.",
"SIMULATED — brief menyebut 'campaign launch minggu depan' tanpa final landing URL, creative IDs, tracking owner, or signed approval. Ad Ops perlu mengembalikan blocker list sebelum setup, bukan mengarang detail.",
["<b>Read the approved brief.</b> Ekstrak objective, platform, markets, dates, budget, assets, audience, tracking, and KPI.","<b>Build object map.</b> Tentukan hierarchy sesuai platform dan relasi campaign/placement/creative/tag.","<b>Apply taxonomy.</b> Gunakan naming yang memuat brand, market, objective, platform, format, audience, flight, and version.","<b>Validate completeness.</b> Gunakan required-field checks, owner, approval, dependency, and status."],
"Buat trafficking sheet lintas Meta, Google, TikTok, dan direct placement dengan IDs, names, asset specs, URLs, tags, flight, budget, targeting, owners, approval, and status.",
[["Mengapa trafficking sheet harus mencatat object IDs?","Nama dapat berubah/duplikat; ID membantu traceability, QA, API/report matching, dan handover."],["Apa risiko URL belum final?","Traffic dapat salah arah, tracking parameter hilang, conversion tidak terekam, atau campaign terpaksa dihentikan."],["Apa fungsi version control?","Menghindari asset/setting lama tertayang dan memastikan approval merujuk pada versi final."]],
[["Trafficking sheet","Dokumen instruksi detail konfigurasi campaign."],["Naming taxonomy","Aturan penamaan sistematis untuk objek dan laporan."],["Object ID","Identifier unik dari platform/ad server."],["Required field","Informasi minimum yang wajib sebelum setup/go-live."]],"DPA-T09-CH02"),
G("Creative and placement specifications memastikan asset diterima dan dirender sesuai environment. Periksa dimensions, aspect ratio, file size, format, duration, codec, frame rate, audio, click URL, SSL, safe zone, HTML5, fallbacks, responsive behavior, and platform policy. Spec berubah; selalu cek halaman resmi platform/publisher dan tanggal. Asset approved secara brand belum tentu technically eligible.",
"SIMULATED — satu video 9:16 memiliki file size melebihi limit dan CTA tertutup safe zone; upload gagal atau tampil terpotong. Ad Ops memvalidasi spec sebelum creative delivery deadline.",
["<b>Identify placements.</b> Catat platform, format, dimensions, ratio, duration, size, and technical requirements.","<b>Check rendering.</b> Periksa mobile/desktop, safe zones, subtitle/audio, text legibility, responsive layout, and fallback.","<b>Validate click path.</b> Test URL, redirects, parameters, SSL, deep link, and landing experience.","<b>Store evidence.</b> Simpan spec version/date, preview screenshot, rejection notes, and approval."],
"Buat creative spec matrix untuk 6 placements (display, video, story/reel, native, HTML5, retailer sponsored content). Sertakan sumber resmi, date checked, file limits, CTA, safe zones, fallback, and QA status.",
[["Mengapa creative spec harus bersumber dari dokumen terkini?","Dimensi, limits, file type, placement rules, and policy dapat berubah antar platform dan waktu."],["Apa itu fallback?","Asset atau behavior alternatif saat creative utama tidak didukung environment/placement."],["Apa yang diperiksa pada click URL selain destination?","Redirect, query parameters, UTMs, macros, SSL, deep-link behavior, and tracking events."]],
[["Aspect ratio","Perbandingan lebar dan tinggi asset."],["Safe zone","Area aman agar teks/visual tidak tertutup UI."],["HTML5 creative","Asset iklan interaktif berbasis teknologi web."],["Fallback","Alternatif creative/behavior jika asset utama tidak kompatibel."]],"DPA-T09-CH03"),
G("Tagging dan tracking memiliki fungsi berbeda. Platform pixel/SDK/CAPI merekam events; UTM memberi label traffic; ad-server placement tag memanggil creative/delivery; click tracker merekam click redirect; impression tracker mengukur exposure; Floodlight mengukur activity di Campaign Manager 360. Ad Ops harus mengetahui siapa memasang, siapa memverifikasi, data apa yang dikirim, consent dependency, and deduplication.",
"SIMULATED — UTM ditambahkan ke URL tetapi purchase pixel tidak terpicu. GA4 dapat membaca campaign source namun platform tidak menerima conversion signal; keduanya bukan pengganti satu sama lain.",
["<b>Build tag map.</b> Catat tag, function, platform, event, parameters, trigger, owner, and destination.","<b>Validate consent.</b> Tentukan behavior untuk consent granted/denied sesuai implementation and legal requirements.","<b>Test firing.</b> Gunakan Preview/Tag Assistant, pixel diagnostics, test events, click test, and network/tag evidence.","<b>Reconcile events.</b> Check duplicates, missing events, parameters, identifiers, time zone, and attribution windows."],
"Buat cross-platform tag map untuk Google tag/GA4, GTM, Meta Pixel/CAPI, TikTok Pixel/Events API, CM360/Floodlight, click/impression tracker, and UTM; sertakan QA cases.",
[["Apa perbedaan UTM dan pixel?","UTM memberi label source/medium/campaign pada traffic; pixel merekam event/interaksi untuk platform measurement."],["Mengapa server-side CAPI bukan sekadar tag lain?","Ia mengirim event dari server dengan identity/consent/deduplication controls yang berbeda dari browser pixel."],["Apa bukti tag benar-benar bekerja?","Test event/log, expected parameters, trigger condition, no duplicate, consent behavior, and platform diagnostics."]],
[["UTM","Parameter URL untuk klasifikasi campaign source/medium."],["Pixel","Script/client-side event tracking di browser."],["CAPI/Events API","Server-side event transmission ke platform."],["Floodlight","Campaign Manager 360 activity/conversion tracking."]],"DPA-T09-CH04"),
G("Ad-server setup seperti CM360 menyusun advertiser, campaign, site, placement, ad, creative, and trackers. Placement mewakili inventory slot dan menghasilkan tag; ad mengontrol delivery/rotation; creative merupakan asset. Floodlight activities memakai counting method, activity group, value, and conversion window. Implementasi harus konsisten dengan naming, click tags, publisher requirements, and reporting.",
"SIMULATED — placement dibuat untuk 300×250 display namun ad creative dipasang 320×50. Publisher menerima tag tetapi tidak merender dengan benar. QA harus mencocokkan placement size, ad, creative, and tag.",
["<b>Build hierarchy.</b> Rancang advertiser/campaign/site/placement/ad/creative relationship.","<b>Define Floodlight.</b> Tentukan activity, group, counting method, value, tag, and window sesuai business action.","<b>Generate and validate tags.</b> Periksa placement tag, click tracker, SSL, publisher implementation guide, and macros.","<b>Test delivery.</b> Simulasikan ad request/rendering, click, and conversion; catat publisher acceptance."],
"Buat CM360 setup blueprint: advertiser, campaign, sites, placements, ads, creatives, Floodlight activity groups, counting methods, tags, and QA evidence. Labeli as design simulation.",
[["Apa beda placement dan creative?","Placement adalah slot/inventory; creative adalah asset yang ditayangkan dalam slot tersebut."],["Apa fungsi Floodlight counting method?","Menentukan bagaimana activity dihitung agar conversion metric sesuai definisi bisnis."],["Apa yang perlu diserahkan ke publisher?","Correct ad/placement tags, spec, click macro, dates, creative, implementation instructions, and QA contacts."]],
[["Placement","Representasi slot inventory dalam ad server."],["Creative","Asset iklan yang ditayangkan."],["Floodlight activity","Event yang diukur oleh CM360."],["Counting method","Aturan penghitungan activity/conversion."]],"DPA-T09-CH05"),
G("Pre-launch QA adalah quality gate sebelum campaign live. Checklist harus mencakup object setup, budget, flight, targeting, creative rendering, URL, redirects, tags/events, consent, policy, exclusions, frequency, geo, language, conversion settings, publisher acceptance, and sign-off. Upload success tidak berarti siap launch. Severity levels membantu menentukan blocker, major issue, and minor issue.",
"SIMULATED — campaign sudah active tetapi landing URL masih staging dan conversion event duplicate. QA harus menghentikan launch sampai blocker diselesaikan, bukan hanya mengirim screenshot campaign status.",
["<b>Prepare test plan.</b> Tulis expected/actual result untuk each field, event, creative, and placement.","<b>Execute end-to-end test.</b> Check ad preview/render, click, landing, redirects, conversion, analytics, consent, and platform acceptance.","<b>Classify issues.</b> Tentukan severity, impact, owner, due time, evidence, and retest.","<b>Obtain sign-off.</b> Simpan approval dari media owner, client, creative, data, and campaign owner."],
"Buat pre-launch QA checklist dengan 30 test cases, expected vs actual, severity, owner, evidence link, status, retest, and formal go/no-go decision.",
[["Mengapa status campaign active belum cukup sebagai QA?","Campaign bisa active tetapi asset, URL, tag, targeting, consent, atau conversion path salah."],["Apa contoh blocker?","Wrong landing URL, non-working conversion tag, unapproved claim, incorrect geo/date/budget, or rejected creative."],["Apa tujuan severity classification?","Membantu memprioritaskan issue berdasarkan impact dan mencegah low-priority issue menahan launch tanpa alasan."]],
[["Pre-launch QA","Verifikasi menyeluruh sebelum campaign go-live."],["Go/no-go","Keputusan launch atau tahan berdasarkan acceptance criteria."],["Severity","Tingkat dampak/urgency dari issue."],["Sign-off","Persetujuan resmi bahwa standar launch terpenuhi."]],"DPA-T09-CH06"),
G("Live monitoring membandingkan planned dengan actual delivery dan memisahkan media issue dari tracking issue. Pantau spend, pacing, impressions, clicks, conversions, cost metrics, rejection, placement status, frequency, viewability/IVT, site errors, and reporting lag. Troubleshooting harus hirarkis: data signal, tag, creative, targeting, platform eligibility, inventory, budget/bid, and publisher—not langsung menaikkan spend.",
"SIMULATED — spend normal tetapi conversions turun mendadak. Klik dan landing sessions tetap normal, tetapi purchase event hilang setelah website release. Ini tracking/site issue, bukan bid atau audience problem.",
["<b>Set monitoring cadence.</b> Definisikan daily/weekly metrics, owner, thresholds, alert, and reporting time zone.","<b>Isolate symptoms.</b> Bandingkan delivery, click, session, event, creative, placement, and CRM outcomes.","<b>Follow diagnostic tree.</b> Periksa data/latency, tag/event, URL/page, creative, targeting, bid/budget, supply, and approvals.","<b>Record action.</b> Simpan root-cause evidence, impact, mitigation, owner, and verification after fix."],
"Buat monitoring dashboard/log dan troubleshooting tree untuk underdelivery, sudden spend spike, rejection, broken click URL, lost conversion event, and discrepancy.",
[["Mengapa conversion drop tidak selalu masalah ads delivery?","Site, checkout, consent, tracking, price, stock, CRM, or reporting latency dapat berubah meski delivery normal."],["Apa urutan troubleshooting yang disiplin?","Isolasi simptom dan cek data/tag/page/creative/settings/supply sebelum mengubah bid/budget."],["Mengapa action log penting?","Membuat root cause, owner, risk, and recovery dapat diaudit dan mencegah perubahan berulang tanpa evidence."]],
[["Pacing","Kecepatan spend/delivery terhadap rencana."],["Underdelivery","Delivery aktual lebih rendah dari komitmen/target."],["Rejection","Penolakan asset/campaign oleh platform/publisher/policy."],["Troubleshooting tree","Urutan diagnosis untuk menemukan sumber issue."]],"DPA-T09-CH07"),
G("Platform discrepancy muncul karena definisi event, click/impression filtering, attribution window, view-through, timezone, cut-off, consent, deduplication, latency, and identity berbeda. Ad Ops tidak boleh langsung menyebut salah satu sistem rusak sebelum membandingkan apples-to-apples. Reconciliation harus menyamakan scope, unit, date, event definition, and eligibility.",
"SIMULATED — Meta reports 120 purchase conversions, GA4 shows 96 sessions with purchase, CM360 reports 105 Floodlight activities. Differences may stem from attribution and dedupe; event map and transaction IDs are needed.",
["<b>Define comparable scope.</b> Samakan date, timezone, campaign, placement, event, device, and attribution window.","<b>Check processing.</b> Review invalid traffic, consent, browser restrictions, event latency, duplicate, and redirects.","<b>Build reconciliation table.</b> Compare each system's unit, count rule, source, and known exclusions.","<b>Explain residual variance.</b> Separate resolved causes, plausible causes, and unverified differences."],
"Buat discrepancy report tiga platform: data dictionary, event mapping, timezone/cutoff, click/view windows, dedupe, consent, latency, matched/unknown variance, and recommendations.",
[["Apa arti apples-to-apples reconciliation?","Perbandingan dengan unit, window, timezone, event, scope, dan eligibility yang setara."],["Mengapa click count tidak sama dengan GA4 sessions?","Click dapat gagal load, user close page, redirect, consent, browser block, or multiple clicks per session."],["Kapan discrepancy perlu dieskalasi?","Jika di luar tolerance/contract, memengaruhi billing/optimization, atau sumber perbedaan tidak dapat dijelaskan."]],
[["Attribution discrepancy","Perbedaan count akibat aturan credit/window."],["Data latency","Waktu antara event terjadi dan data tersedia."],["Deduplication","Penghapusan event duplikat menurut identifier/rule."],["Cut-off","Batas waktu/periode yang dipakai untuk reporting."]],"DPA-T09-CH08"),
G("Billing reconciliation and process control menjaga kesesuaian booking, delivery, dan invoice. Ad Ops mengumpulkan IO, placement logs, rate, booked volume, billable basis, currency, tax, discount, bonus, makegood, platform fees, and proof. Finance controls perlu separation of duties, version history, access controls, and archive. Operational efficiency bukan berarti menghapus quality gates.",
"SIMULATED — vendor menagih 1 juta impressions tetapi proof delivery hanya 920 ribu. Contract menyebut 95% tolerance dan bonus impressions terpisah. Tim perlu menghitung shortfall dan memeriksa billable basis sebelum mengajukan credit.",
["<b>Match financial records.</b> Cocokkan IO, platform booking, delivery, invoice, rate, tax, fees, and proof.","<b>Recalculate billable.</b> Pisahkan booked, delivered, bonus, makegood, tolerance, and chargeable volume.","<b>Govern process.</b> Gunakan approver, access controls, change logs, naming, and archived evidence.","<b>Improve root process.</b> Catat recurring issue, SLA, automation candidates, and control owner."],
"Buat billing reconciliation pack untuk dua vendor: IO-vs-invoice, delivery proof, billable calculation, variance, adjustment, approval, audit trail, and process improvement memo.",
[["Mengapa delivered impressions belum tentu billable impressions?","Kontrak dapat memiliki tolerance, excluded events, bonus, or alternative billable definitions."],["Apa risiko satu orang mengatur dan menyetujui invoice sendiri?","Segregation of duties lemah sehingga fraud/error lebih sulit dideteksi."],["Apa output operational review yang berguna?","Recurring issue, control gap, SLA, owners, automation opportunities, and measurable process improvement."]],
[["Billable basis","Unit/definisi delivery yang menjadi dasar tagihan."],["Segregation of duties","Pemisahan tanggung jawab agar tidak ada satu pihak mengontrol seluruh proses."],["Audit trail","Jejak dokumen dan keputusan yang dapat ditelusuri."],["SLA","Service-level agreement untuk waktu/kualitas layanan."]],"DPA-T09-CH09"),
G("Capstone Ad Operations menyatukan operation chain multi-platform: brief, trafficking, creative spec, tags, ad-server/platform setup, QA, go-live, monitoring, troubleshooting, discrepancy, billing, and documentation. Keberhasilan dinilai dari accuracy, traceability, risk control, and timely delivery—not creative strategy or budget optimization. Setiap contoh account/data harus berlabel SIMULATED dan tidak menyiratkan akses live.",
"SIMULATED — agency menjalankan launch lintas Google, Meta, TikTok, DV360/CM360, dan satu publisher direct. Capstone memastikan object IDs, creative, tracking, approvals, reporting, and billing traceable.",
["<b>Translate requirements.</b> Ubah approved brief menjadi platform/object/owner/specification matrix.","<b>Build and validate.</b> Siapkan trafficking, tags, URL, creative, tracking, and platform config.","<b>Launch and operate.</b> Simulasikan go-live, monitor, issue triage, and escalation.","<b>Close and audit.</b> Reconcile reporting/billing, archive evidence, and recommend control improvements."],
"Siapkan operational case pack: master brief, cross-platform trafficking sheet, creative spec matrix, tag map, CM360/Floodlight design, QA evidence, go-live checklist, monitoring log, incident report, discrepancy reconciliation, invoice pack, and process review.",
[["Apa bukti Ad Ops yang siap portofolio?","Traceable operational artefacts: trafficking sheet, tags, QA evidence, approvals, monitoring, discrepancy, and billing reconciliation."],["Apa yang tidak boleh diklaim dari simulasi?","Tidak boleh mengklaim real client account access, live campaign delivery, spend, or campaign outcomes."],["Bagaimana Ad Ops menunjukkan nilai bisnis?","Mengurangi launch errors, data loss, downtime, underdelivery, billing disputes, and audit risk."]],
[["Operational control","Prosedur untuk menjaga akurasi dan reliability proses."],["Campaign artefact","Dokumen/file yang membuktikan konfigurasi dan keputusan."],["Incident report","Catatan issue, impact, root cause, fix, and prevention."],["Operational review","Evaluasi proses, quality, efficiency, and improvements."]],"DPA-T09-CH10")
]
};
